-- Apply after merge and SHA256 verification of every new public image.
BEGIN;
DO $publish$
DECLARE
 bundles jsonb := $content$[[{"language":"es","slug":"sabajon-colombiano","title":"Sabajón colombiano","seo":{"title":"Sabajón colombiano","description":"Sabajón colombiano cremoso con leche, yemas cocidas y canela. Receta navideña con aguardiente o brandy, opción sin alcohol y conservación en frío.","faq":[{"q":"¿Cómo evito que se corte?","a":"Mantén fuego bajo y remueve sin parar. Retira al llegar a 82–84 °C; hervir puede cuajar las yemas."},{"q":"¿Se puede preparar sin alcohol?","a":"Sí. Cambia los 150 ml de licor por 150 ml de leche pasteurizada fría y conserva la bebida en nevera hasta 3 días."}],"author":"Néstor Bastidas","image_alt":"Sabajón colombiano","additional_time_minutes":260,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-16x9.webp"]},"summary":"El sabajón colombiano es una bebida navideña cremosa de leche y yemas cocidas, perfumada con canela. Se sirve frío y en copas pequeñas. La versión con aguardiente o brandy es solo para adultos.","ingredients":[{"name":"leche entera pasteurizada","amount":"1000","unit":"ml"},{"name":"yemas de huevo, unas 6 grandes; pesar 108 g","amount":"108","unit":"g"},{"name":"azúcar blanca","amount":"150","unit":"g"},{"name":"canela molida","amount":"1","unit":"g"},{"name":"brandy al 40 % vol o aguardiente colombiano","amount":"150","unit":"ml"}],"steps":[{"title":"Calienta la leche","content":"Calienta los 1000 ml de leche con la canela a 80–85 °C durante 5–8 minutos, sin dejar que hierva.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-01.webp","image_alt":"Calienta la leche"},{"title":"Bate las yemas","content":"Bate los 108 g de yemas con los 150 g de azúcar durante 2 minutos, hasta obtener una mezcla uniforme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-02.webp","image_alt":"Bate las yemas"},{"title":"Templa las yemas","content":"Incorpora poco a poco 250 ml de la leche caliente a las yemas, batiendo continuamente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-03.webp","image_alt":"Templa las yemas"},{"title":"Cocina la crema","content":"Cocina la mezcla de yemas con la leche restante a fuego bajo, removiendo 8–12 minutos hasta alcanzar 82–84 °C y cubrir ligeramente una cuchara. No debe hervir; toda la crema debe superar 71 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-04.webp","image_alt":"Cocina la crema"},{"title":"Enfría la base","content":"Enfría la crema en un recipiente metálico dentro de un baño de agua con hielo durante 15–20 minutos, removiendo hasta bajar a 20 °C o menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-05.webp","image_alt":"Enfría la base"},{"title":"Añade el licor","content":"Incorpora los 150 ml de brandy o aguardiente a la base fría. Para la versión sin alcohol, usa 150 ml de leche pasteurizada fría en su lugar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-06.webp","image_alt":"Añade el licor"},{"title":"Refrigera","content":"Refrigera en una botella limpia y tapada durante al menos 4 horas a 4 °C o menos. Debe entrar en la nevera antes de 2 horas desde el final de la cocción.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-07.webp","image_alt":"Refrigera"},{"title":"Sirve frío","content":"Agita suavemente la botella y reparte el sabajón frío en 8 porciones pequeñas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp","image_alt":"Sirve frío"}],"notes":"<p>La versión con alcohol es solo para adultos. Para hacerlo sin alcohol, sustituye los 150 ml de licor por 150 ml de leche pasteurizada fría; mantén la misma cocción de las yemas. Conserva ambas versiones tapadas a 4 °C o menos y consume en un máximo de 3 días desde su preparación. El licor no sustituye la cocción ni alarga ese plazo. Contiene leche y huevo.</p>","category":"Bebidas","course":"Bebidas","cuisine":"Colombiana","difficulty":"Intermedia","servings":8,"prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":295,"excerpt":"El sabajón colombiano es una bebida navideña cremosa de leche y yemas cocidas, perfumada con canela. Se sirve frío y en copas pequeñas. La versión con aguardiente o brandy es solo para adultos.","content_html":"","keywords":["Sabajón colombiano"],"gallery":[],"public_path":"/sabajon-colombiano","nutrition":{"calories":236.3,"protein_g":6.2,"carbs_g":25.5,"fat_g":7.8,"serving_size":"1/8","estimated":true,"source":"USDA FoodData Central / Standard Reference; ethanol energy factor","method":"Suma de nutrientes de ingredientes según las cantidades, dividida entre las raciones.","note":"Por 1 de 8 porciones, calculada con 150 ml de brandy al 40 % vol y todo su alcohol. Con aguardiente, los valores dependen de su graduación y azúcar; la versión con leche en lugar del licor tiene otra nutrición.","alcohol_g":5.9},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp"},{"language":"en","slug":"colombian-sabajon-eggnog","title":"Colombian Sabajón Eggnog","seo":{"title":"Colombian Sabajón Eggnog","description":"Make creamy Colombian sabajón with milk, cooked egg yolks and cinnamon. A Christmas drink with brandy or aguardiente, an alcohol-free option and storage tips.","faq":[{"q":"How do I keep the custard smooth?","a":"Use low heat and stir constantly. Remove at 82–84 °C; boiling can scramble the yolks."},{"q":"Can I make it without alcohol?","a":"Yes. Replace the 150 ml spirit with 150 ml cold pasteurized milk and refrigerate for no more than 3 days."}],"author":"Néstor Bastidas","image_alt":"Colombian Sabajón Eggnog","additional_time_minutes":260,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-16x9.webp"]},"summary":"Sabajón is a creamy Colombian Christmas drink made with milk, gently cooked egg yolks and cinnamon. Serve it cold in small glasses. The version containing brandy or aguardiente is for adults only.","ingredients":[{"name":"pasteurized whole milk","amount":"1000","unit":"ml"},{"name":"egg yolks, about 6 large; weigh 108 g","amount":"108","unit":"g"},{"name":"white sugar","amount":"150","unit":"g"},{"name":"ground cinnamon","amount":"1","unit":"g"},{"name":"40% ABV brandy or Colombian aguardiente","amount":"150","unit":"ml"}],"steps":[{"title":"Warm the milk","content":"Heat the 1000 ml milk with the cinnamon to 80–85 °C for 5–8 minutes without boiling.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-01.webp","image_alt":"Warm the milk"},{"title":"Whisk the yolks","content":"Whisk the 108 g egg yolks with the 150 g sugar for 2 minutes until evenly blended.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-02.webp","image_alt":"Whisk the yolks"},{"title":"Temper the yolks","content":"Gradually whisk 250 ml of the hot milk into the yolks, whisking continuously.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-03.webp","image_alt":"Temper the yolks"},{"title":"Cook the custard","content":"Cook the yolk mixture with the remaining milk over low heat, stirring for 8–12 minutes until it reaches 82–84 °C and lightly coats a spoon. Do not boil; the entire custard must exceed 71 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-04.webp","image_alt":"Cook the custard"},{"title":"Cool the base","content":"Cool the custard in a metal bowl set in an ice-water bath for 15–20 minutes, stirring until it reaches 20 °C or below.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-05.webp","image_alt":"Cool the base"},{"title":"Add the spirit","content":"Stir the 150 ml brandy or aguardiente into the cool base. For an alcohol-free version, replace it with 150 ml cold pasteurized milk.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-06.webp","image_alt":"Add the spirit"},{"title":"Chill","content":"Refrigerate in a clean, covered bottle for at least 4 hours at 4 °C or below. Refrigerate within 2 hours of finishing cooking.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-07.webp","image_alt":"Chill"},{"title":"Serve cold","content":"Gently shake the bottle and divide the cold sabajón into 8 small servings.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp","image_alt":"Serve cold"}],"notes":"<p>The alcoholic version is for adults only. For alcohol-free sabajón, replace the 150 ml spirit with 150 ml cold pasteurized milk and cook the yolks exactly as directed. Keep either version covered at 4 °C or below and use within 3 days of making it. Alcohol does not replace cooking or extend this storage time. Contains milk and egg.</p>","category":"Drinks","course":"Drinks","cuisine":"Colombian","difficulty":"Medium","servings":8,"prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":295,"excerpt":"Sabajón is a creamy Colombian Christmas drink made with milk, gently cooked egg yolks and cinnamon. Serve it cold in small glasses. The version containing brandy or aguardiente is for adults only.","content_html":"","keywords":["Colombian Sabajón Eggnog"],"gallery":[],"public_path":"/en/colombian-sabajon-eggnog","nutrition":{"calories":236.3,"protein_g":6.2,"carbs_g":25.5,"fat_g":7.8,"serving_size":"1/8","estimated":true,"source":"USDA FoodData Central / Standard Reference; ethanol energy factor","method":"Ingredient nutrients summed for the stated quantities and divided by servings.","note":"Per 1 of 8 servings, calculated with 150 ml 40% ABV brandy and all its alcohol. Aguardiente values depend on its strength and sugar content; replacing the spirit with milk changes the nutrition.","alcohol_g":5.9},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp"},{"language":"de","slug":"kolumbianischer-sabajon-eierlikoer","title":"Kolumbianischer Sabajón","seo":{"title":"Kolumbianischer Sabajón","description":"Cremiger kolumbianischer Sabajón mit Milch, gegartem Eigelb und Zimt. Weihnachtsrezept mit Brandy oder Aguardiente, alkoholfreier Variante und Kühltipps.","faq":[{"q":"Wie bleibt die Creme glatt?","a":"Bei kleiner Hitze ständig rühren und bei 82–84 °C vom Herd nehmen. Beim Kochen kann das Eigelb stocken."},{"q":"Geht es ohne Alkohol?","a":"Ja. Die 150 ml Spirituose durch 150 ml kalte pasteurisierte Milch ersetzen und höchstens 3 Tage im Kühlschrank aufbewahren."}],"author":"Néstor Bastidas","image_alt":"Kolumbianischer Sabajón","additional_time_minutes":260,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-16x9.webp"]},"summary":"Sabajón gehört in Kolumbien zur Weihnachtszeit: ein cremiges Getränk aus Milch, schonend gegartem Eigelb und Zimt. Es wird kalt in kleinen Gläsern serviert. Die Variante mit Alkohol ist nur für Erwachsene.","ingredients":[{"name":"pasteurisierte Vollmilch","amount":"1000","unit":"ml"},{"name":"Eigelb, etwa 6 große; 108 g abwiegen","amount":"108","unit":"g"},{"name":"weißer Zucker","amount":"150","unit":"g"},{"name":"gemahlener Zimt","amount":"1","unit":"g"},{"name":"Brandy mit 40 % vol oder kolumbianischer Aguardiente","amount":"150","unit":"ml"}],"steps":[{"title":"Milch erwärmen","content":"Die 1000 ml Milch mit dem Zimt 5–8 Minuten auf 80–85 °C erhitzen, ohne sie kochen zu lassen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-01.webp","image_alt":"Milch erwärmen"},{"title":"Eigelb aufschlagen","content":"Die 108 g Eigelb mit den 150 g Zucker 2 Minuten zu einer gleichmäßigen Masse schlagen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-02.webp","image_alt":"Eigelb aufschlagen"},{"title":"Eigelb angleichen","content":"250 ml heiße Milch nach und nach unter ständigem Schlagen zum Eigelb geben.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-03.webp","image_alt":"Eigelb angleichen"},{"title":"Creme garen","content":"Die Eigelbmischung mit der übrigen Milch bei kleiner Hitze 8–12 Minuten unter Rühren auf 82–84 °C bringen, bis sie einen Löffel dünn überzieht. Nicht kochen; die gesamte Creme muss über 71 °C erreichen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-04.webp","image_alt":"Creme garen"},{"title":"Grundmasse kühlen","content":"Die Creme in einer Metallschüssel im Eiswasserbad 15–20 Minuten unter Rühren auf höchstens 20 °C abkühlen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-05.webp","image_alt":"Grundmasse kühlen"},{"title":"Spirituose zugeben","content":"150 ml Brandy oder Aguardiente in die kalte Grundmasse rühren. Für die alkoholfreie Variante stattdessen 150 ml kalte pasteurisierte Milch verwenden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-06.webp","image_alt":"Spirituose zugeben"},{"title":"Kalt stellen","content":"In einer sauberen, verschlossenen Flasche mindestens 4 Stunden bei höchstens 4 °C kühlen. Spätestens 2 Stunden nach dem Garen in den Kühlschrank stellen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-07.webp","image_alt":"Kalt stellen"},{"title":"Kalt servieren","content":"Die Flasche sanft schütteln und den kalten Sabajón auf 8 kleine Portionen verteilen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp","image_alt":"Kalt servieren"}],"notes":"<p>Die Variante mit Alkohol ist nur für Erwachsene. Alkoholfrei wird das Getränk mit 150 ml kalter pasteurisierter Milch anstelle der Spirituose; das Eigelb genauso garen. Beide Varianten verschlossen bei höchstens 4 °C lagern und innerhalb von 3 Tagen ab Zubereitung verbrauchen. Alkohol ersetzt das Garen nicht und verlängert diese Frist nicht. Enthält Milch und Ei.</p>","category":"Getränke","course":"Getränke","cuisine":"Kolumbianisch","difficulty":"Mittel","servings":8,"prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":295,"excerpt":"Sabajón gehört in Kolumbien zur Weihnachtszeit: ein cremiges Getränk aus Milch, schonend gegartem Eigelb und Zimt. Es wird kalt in kleinen Gläsern serviert. Die Variante mit Alkohol ist nur für Erwachsene.","content_html":"","keywords":["Kolumbianischer Sabajón"],"gallery":[],"public_path":"/de/kolumbianischer-sabajon-eierlikoer","nutrition":{"calories":236.3,"protein_g":6.2,"carbs_g":25.5,"fat_g":7.8,"serving_size":"1/8","estimated":true,"source":"USDA FoodData Central / Standard Reference; ethanol energy factor","method":"Nährstoffe der angegebenen Zutatenmengen addiert und durch die Portionen geteilt.","note":"Für 1 von 8 Portionen, berechnet mit 150 ml Brandy mit 40 % vol einschließlich des gesamten Alkohols. Bei Aguardiente hängen die Werte von Alkohol- und Zuckergehalt ab; Milch statt Spirituose verändert die Nährwerte.","alcohol_g":5.9},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp"},{"language":"fr","slug":"sabajon-colombien-lait-de-poule","title":"Sabajón colombien","seo":{"title":"Sabajón colombien","description":"Sabajón colombien crémeux au lait, jaunes cuits et cannelle. Boisson de Noël au brandy ou à l’aguardiente, avec option sans alcool et conseils de conservation.","faq":[{"q":"Comment éviter une crème granuleuse ?","a":"Remuez sans arrêt à feu doux et retirez à 82–84 °C. L’ébullition risque de coaguler les jaunes."},{"q":"Peut-on supprimer l’alcool ?","a":"Oui. Remplacez les 150 ml d’alcool par 150 ml de lait pasteurisé froid et gardez au réfrigérateur 3 jours maximum."}],"author":"Néstor Bastidas","image_alt":"Sabajón colombien","additional_time_minutes":260,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-16x9.webp"]},"summary":"Le sabajón accompagne les fêtes de Noël en Colombie. Ce lait de poule onctueux aux jaunes cuits et à la cannelle se déguste froid, en petits verres. La version alcoolisée est réservée aux adultes.","ingredients":[{"name":"lait entier pasteurisé","amount":"1000","unit":"ml"},{"name":"jaunes d’œufs, environ 6 gros ; peser 108 g","amount":"108","unit":"g"},{"name":"sucre blanc","amount":"150","unit":"g"},{"name":"cannelle moulue","amount":"1","unit":"g"},{"name":"brandy à 40 % vol ou aguardiente colombien","amount":"150","unit":"ml"}],"steps":[{"title":"Chauffez le lait","content":"Chauffez les 1000 ml de lait avec la cannelle à 80–85 °C pendant 5–8 minutes, sans ébullition.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-01.webp","image_alt":"Chauffez le lait"},{"title":"Fouettez les jaunes","content":"Fouettez les 108 g de jaunes avec les 150 g de sucre pendant 2 minutes pour obtenir un mélange homogène.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-02.webp","image_alt":"Fouettez les jaunes"},{"title":"Tempérez les jaunes","content":"Versez progressivement 250 ml du lait chaud sur les jaunes en fouettant sans arrêt.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-03.webp","image_alt":"Tempérez les jaunes"},{"title":"Cuisez la crème","content":"Cuisez les jaunes avec le reste du lait à feu doux en remuant 8–12 minutes, jusqu’à 82–84 °C : la crème doit napper légèrement une cuillère. Ne faites pas bouillir ; toute la crème doit dépasser 71 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-04.webp","image_alt":"Cuisez la crème"},{"title":"Refroidissez la base","content":"Refroidissez la crème dans un récipient métallique posé dans un bain d’eau glacée pendant 15–20 minutes, en remuant jusqu’à 20 °C ou moins.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-05.webp","image_alt":"Refroidissez la base"},{"title":"Ajoutez l’alcool","content":"Incorporez les 150 ml de brandy ou d’aguardiente à la base froide. Pour la version sans alcool, remplacez-les par 150 ml de lait pasteurisé froid.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-06.webp","image_alt":"Ajoutez l’alcool"},{"title":"Réfrigérez","content":"Réfrigérez dans une bouteille propre et fermée au moins 4 heures à 4 °C ou moins. Mettez au réfrigérateur dans les 2 heures suivant la cuisson.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-07.webp","image_alt":"Réfrigérez"},{"title":"Servez froid","content":"Agitez doucement la bouteille et répartissez le sabajón froid en 8 petites portions.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp","image_alt":"Servez froid"}],"notes":"<p>La version alcoolisée est réservée aux adultes. Pour une version sans alcool, remplacez les 150 ml d’alcool par 150 ml de lait pasteurisé froid, sans modifier la cuisson des jaunes. Gardez les deux versions fermées à 4 °C ou moins et consommez sous 3 jours après préparation. L’alcool ne remplace pas la cuisson et ne prolonge pas ce délai. Contient du lait et de l’œuf.</p>","category":"Boissons","course":"Boissons","cuisine":"Colombienne","difficulty":"Intermédiaire","servings":8,"prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":295,"excerpt":"Le sabajón accompagne les fêtes de Noël en Colombie. Ce lait de poule onctueux aux jaunes cuits et à la cannelle se déguste froid, en petits verres. La version alcoolisée est réservée aux adultes.","content_html":"","keywords":["Sabajón colombien"],"gallery":[],"public_path":"/fr/sabajon-colombien-lait-de-poule","nutrition":{"calories":236.3,"protein_g":6.2,"carbs_g":25.5,"fat_g":7.8,"serving_size":"1/8","estimated":true,"source":"USDA FoodData Central / Standard Reference; ethanol energy factor","method":"Somme des nutriments des quantités indiquées, divisée par le nombre de portions.","note":"Pour 1 portion sur 8, calculée avec 150 ml de brandy à 40 % vol, alcool compris en totalité. Les valeurs de l’aguardiente varient avec son degré et son sucre ; remplacer l’alcool par du lait modifie les apports.","alcohol_g":5.9},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp"},{"language":"it","slug":"sabajon-colombiano-zabaione-liquore","title":"Sabajón colombiano","seo":{"title":"Sabajón colombiano","description":"Sabajón colombiano cremoso con latte, tuorli cotti e cannella. Bevanda natalizia con brandy o aguardiente, variante analcolica e consigli per conservarla.","faq":[{"q":"Come evitare che la crema impazzisca?","a":"Usa fuoco basso e mescola continuamente. Togli dal fuoco a 82–84 °C: il bollore può far coagulare i tuorli."},{"q":"Si può fare senza alcol?","a":"Sì. Sostituisci i 150 ml di liquore con 150 ml di latte pastorizzato freddo e conserva in frigorifero per non più di 3 giorni."}],"author":"Néstor Bastidas","image_alt":"Sabajón colombiano","additional_time_minutes":260,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-16x9.webp"]},"summary":"Il sabajón colombiano è una bevanda natalizia cremosa a base di latte, tuorli cotti dolcemente e cannella. Si serve freddo in piccoli bicchieri. La versione con alcol è riservata agli adulti.","ingredients":[{"name":"latte intero pastorizzato","amount":"1000","unit":"ml"},{"name":"tuorli, circa 6 grandi; pesarne 108 g","amount":"108","unit":"g"},{"name":"zucchero bianco","amount":"150","unit":"g"},{"name":"cannella in polvere","amount":"1","unit":"g"},{"name":"brandy al 40% vol oppure aguardiente colombiano","amount":"150","unit":"ml"}],"steps":[{"title":"Scalda il latte","content":"Scalda i 1000 ml di latte con la cannella a 80–85 °C per 5–8 minuti, senza far bollire.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-01.webp","image_alt":"Scalda il latte"},{"title":"Sbatti i tuorli","content":"Sbatti i 108 g di tuorli con i 150 g di zucchero per 2 minuti, fino a ottenere un composto uniforme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-02.webp","image_alt":"Sbatti i tuorli"},{"title":"Tempera i tuorli","content":"Versa gradualmente 250 ml di latte caldo nei tuorli, continuando a sbattere.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-03.webp","image_alt":"Tempera i tuorli"},{"title":"Cuoci la crema","content":"Cuoci il composto di tuorli con il latte rimasto a fuoco basso, mescolando per 8–12 minuti fino a 82–84 °C: deve velare leggermente un cucchiaio. Non far bollire; tutta la crema deve superare 71 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-04.webp","image_alt":"Cuoci la crema"},{"title":"Raffredda la base","content":"Raffredda la crema in un recipiente metallico immerso in acqua e ghiaccio per 15–20 minuti, mescolando fino a 20 °C o meno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-05.webp","image_alt":"Raffredda la base"},{"title":"Aggiungi il liquore","content":"Incorpora i 150 ml di brandy o aguardiente alla base fredda. Per la versione analcolica, sostituiscili con 150 ml di latte pastorizzato freddo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-06.webp","image_alt":"Aggiungi il liquore"},{"title":"Metti in frigorifero","content":"Lascia in una bottiglia pulita e chiusa per almeno 4 ore a 4 °C o meno. Riponi in frigorifero entro 2 ore dalla fine della cottura.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-07.webp","image_alt":"Metti in frigorifero"},{"title":"Servi freddo","content":"Agita delicatamente la bottiglia e dividi il sabajón freddo in 8 piccole porzioni.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp","image_alt":"Servi freddo"}],"notes":"<p>La versione alcolica è riservata agli adulti. Per prepararla senza alcol, usa 150 ml di latte pastorizzato freddo al posto del liquore e cuoci i tuorli nello stesso modo. Conserva entrambe le versioni chiuse a 4 °C o meno e consumale entro 3 giorni dalla preparazione. L’alcol non sostituisce la cottura e non prolunga la conservazione. Contiene latte e uova.</p>","category":"Bevande","course":"Bevande","cuisine":"Colombiana","difficulty":"Media","servings":8,"prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":295,"excerpt":"Il sabajón colombiano è una bevanda natalizia cremosa a base di latte, tuorli cotti dolcemente e cannella. Si serve freddo in piccoli bicchieri. La versione con alcol è riservata agli adulti.","content_html":"","keywords":["Sabajón colombiano"],"gallery":[],"public_path":"/it/sabajon-colombiano-zabaione-liquore","nutrition":{"calories":236.3,"protein_g":6.2,"carbs_g":25.5,"fat_g":7.8,"serving_size":"1/8","estimated":true,"source":"USDA FoodData Central / Standard Reference; ethanol energy factor","method":"Somma dei nutrienti delle quantità indicate divisa per il numero di porzioni.","note":"Per 1 delle 8 porzioni, calcolata con 150 ml di brandy al 40% vol e tutto il suo alcol. Con aguardiente i valori dipendono da gradazione e zucchero; sostituire il liquore con latte cambia i nutrienti.","alcohol_g":5.9},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp"},{"language":"ja","slug":"colombia-sabajon","title":"コロンビアのサバホン","seo":{"title":"コロンビアのサバホン","description":"コロンビアのクリスマスに親しまれるサバホン。牛乳、卵黄、砂糖、シナモンで作るなめらかな飲み物です。卵黄に火を通す温度と冷やす時間、ブランデーやアグアルディエンテを加える手順を紹介。お酒を使わない作り方と、冷蔵での保存期間もわかる、家庭向けのレシピです。","faq":[{"q":"なめらかに仕上げるには？","a":"弱火で絶えず混ぜ、82～84 °Cで火から下ろします。沸騰すると卵黄が固まりやすくなります。"},{"q":"お酒なしでも作れますか？","a":"作れます。お酒150 mlを冷たい殺菌済み牛乳150 mlに替え、冷蔵で3日以内に飲み切ります。"}],"author":"Néstor Bastidas","image_alt":"コロンビアのサバホン","additional_time_minutes":260,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-16x9.webp"]},"summary":"サバホンは、牛乳と火を通した卵黄にシナモンをきかせるコロンビアのクリスマスの飲み物。小さなグラスで冷たく楽しみます。ブランデーやアグアルディエンテを加えるものは成人向けです。","ingredients":[{"name":"殺菌済みの成分無調整牛乳","amount":"1000","unit":"ml"},{"name":"卵黄（大きめ約6個分、108 gを量る）","amount":"108","unit":"g"},{"name":"グラニュー糖","amount":"150","unit":"g"},{"name":"シナモンパウダー","amount":"1","unit":"g"},{"name":"アルコール度数40%のブランデー、またはコロンビアのアグアルディエンテ","amount":"150","unit":"ml"}],"steps":[{"title":"牛乳を温める","content":"牛乳1000 mlとシナモンを5～8分かけて80～85 °Cに温めます。沸騰させません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-01.webp","image_alt":"牛乳を温める"},{"title":"卵黄を混ぜる","content":"卵黄108 gと砂糖150 gを泡立て器で2分混ぜ、均一にします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-02.webp","image_alt":"卵黄を混ぜる"},{"title":"卵黄を温度になじませる","content":"温かい牛乳のうち250 mlを卵黄に少しずつ加え、絶えず混ぜます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-03.webp","image_alt":"卵黄を温度になじませる"},{"title":"クリームに火を通す","content":"卵黄の液と残りの牛乳を弱火で8～12分混ぜ、82～84 °Cにします。スプーンを薄く覆うとろみが目安。沸騰させず、全体が71 °Cを超えるようにします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-04.webp","image_alt":"クリームに火を通す"},{"title":"氷水で冷ます","content":"金属のボウルに入れたクリームを氷水に当て、15～20分混ぜながら20 °C以下まで冷まします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-05.webp","image_alt":"氷水で冷ます"},{"title":"お酒を加える","content":"冷めたベースにブランデーまたはアグアルディエンテ150 mlを混ぜます。ノンアルコール版は冷たい殺菌済み牛乳150 mlに置き換えます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-06.webp","image_alt":"お酒を加える"},{"title":"冷蔵する","content":"清潔なふた付きボトルに入れ、4 °C以下で4時間以上冷やします。加熱終了から2時間以内に冷蔵庫に入れてください。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-07.webp","image_alt":"冷蔵する"},{"title":"冷たく出す","content":"ボトルをやさしく振り、冷たいサバホンを小さな8人分に分けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp","image_alt":"冷たく出す"}],"notes":"<p>お酒を加えたものは成人専用です。ノンアルコール版は、お酒150 mlの代わりに冷たい殺菌済み牛乳150 mlを使い、卵黄の加熱は同じように行います。どちらもふたをして4 °C以下で冷蔵し、作ってから3日以内に飲み切ってください。お酒は加熱の代わりにはならず、保存期間も延ばしません。乳・卵を含みます。</p>","category":"飲み物","course":"飲み物","cuisine":"コロンビア料理","difficulty":"中級","servings":8,"prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":295,"excerpt":"サバホンは、牛乳と火を通した卵黄にシナモンをきかせるコロンビアのクリスマスの飲み物。小さなグラスで冷たく楽しみます。ブランデーやアグアルディエンテを加えるものは成人向けです。","content_html":"","keywords":["コロンビアのサバホン"],"gallery":[],"public_path":"/ja/colombia-sabajon","nutrition":{"calories":236.3,"protein_g":6.2,"carbs_g":25.5,"fat_g":7.8,"serving_size":"1/8","estimated":true,"source":"USDA FoodData Central / Standard Reference; ethanol energy factor","method":"材料の分量から栄養を合計し、人数分で割った推定値です。","note":"8等分の1杯分。度数40%のブランデー150 mlと、そのアルコール全量を含めて計算。アグアルディエンテは度数と糖分によって変わります。お酒を牛乳に替えると栄養値も変わります。","alcohol_g":5.9},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp"},{"language":"pt","slug":"sabajon-colombiano","title":"Sabajón colombiano","seo":{"title":"Sabajón colombiano","description":"Sabajón colombiano cremoso com leite, gemas cozidas e canela. Bebida de Natal com brandy ou aguardiente, opção sem álcool e cuidados de conservação.","faq":[{"q":"Como evitar que o creme talhe?","a":"Use fogo baixo e mexa sempre. Retire ao chegar a 82–84 °C; ferver pode coagular as gemas."},{"q":"Posso fazer sem álcool?","a":"Sim. Troque os 150 ml de destilado por 150 ml de leite pasteurizado frio e conserve na geladeira por até 3 dias."}],"author":"Néstor Bastidas","image_alt":"Sabajón colombiano","additional_time_minutes":260,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada-16x9.webp"]},"summary":"O sabajón é uma bebida natalina colombiana feita com leite, gemas cozidas delicadamente e canela. Sirva bem gelado em copinhos. A versão com brandy ou aguardiente é exclusiva para adultos.","ingredients":[{"name":"leite integral pasteurizado","amount":"1000","unit":"ml"},{"name":"gemas, cerca de 6 grandes; pesar 108 g","amount":"108","unit":"g"},{"name":"açúcar branco","amount":"150","unit":"g"},{"name":"canela em pó","amount":"1","unit":"g"},{"name":"brandy a 40% vol ou aguardiente colombiano","amount":"150","unit":"ml"}],"steps":[{"title":"Aqueça o leite","content":"Aqueça os 1000 ml de leite com a canela a 80–85 °C por 5–8 minutos, sem ferver.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-01.webp","image_alt":"Aqueça o leite"},{"title":"Bata as gemas","content":"Bata os 108 g de gemas com os 150 g de açúcar por 2 minutos, até ficar uniforme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-02.webp","image_alt":"Bata as gemas"},{"title":"Tempere as gemas","content":"Acrescente aos poucos 250 ml do leite quente às gemas, batendo sem parar para igualar a temperatura.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-03.webp","image_alt":"Tempere as gemas"},{"title":"Cozinhe o creme","content":"Cozinhe a mistura de gemas com o leite restante em fogo baixo, mexendo por 8–12 minutos até chegar a 82–84 °C e cobrir levemente uma colher. Não deixe ferver; todo o creme deve ultrapassar 71 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-04.webp","image_alt":"Cozinhe o creme"},{"title":"Esfrie a base","content":"Esfrie o creme num recipiente metálico dentro de um banho de água com gelo por 15–20 minutos, mexendo até chegar a 20 °C ou menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-05.webp","image_alt":"Esfrie a base"},{"title":"Adicione o destilado","content":"Misture os 150 ml de brandy ou aguardiente à base fria. Para a versão sem álcool, use no lugar 150 ml de leite pasteurizado frio.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-06.webp","image_alt":"Adicione o destilado"},{"title":"Leve à geladeira","content":"Refrigere numa garrafa limpa e tampada por pelo menos 4 horas a 4 °C ou menos. Leve à geladeira em até 2 horas após terminar a cocção.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/paso-07.webp","image_alt":"Leve à geladeira"},{"title":"Sirva gelado","content":"Agite a garrafa delicadamente e divida o sabajón gelado em 8 pequenas porções.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp","image_alt":"Sirva gelado"}],"notes":"<p>A versão com álcool é exclusiva para adultos. Para fazer sem álcool, troque os 150 ml de destilado por 150 ml de leite pasteurizado frio e mantenha a mesma cocção das gemas. Guarde ambas as versões tampadas a 4 °C ou menos e consuma em até 3 dias após o preparo. O álcool não substitui o cozimento nem prolonga esse prazo. Contém leite e ovo.</p>","category":"Bebidas","course":"Bebidas","cuisine":"Colombiana","difficulty":"Média","servings":8,"prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":295,"excerpt":"O sabajón é uma bebida natalina colombiana feita com leite, gemas cozidas delicadamente e canela. Sirva bem gelado em copinhos. A versão com brandy ou aguardiente é exclusiva para adultos.","content_html":"","keywords":["Sabajón colombiano"],"gallery":[],"public_path":"/pt/sabajon-colombiano","nutrition":{"calories":236.3,"protein_g":6.2,"carbs_g":25.5,"fat_g":7.8,"serving_size":"1/8","estimated":true,"source":"USDA FoodData Central / Standard Reference; ethanol energy factor","method":"Soma dos nutrientes das quantidades indicadas dividida pelo número de porções.","note":"Por 1 das 8 porções, calculada com 150 ml de brandy a 40% vol e todo o álcool. Com aguardiente os valores variam conforme graduação e açúcar; trocar o destilado por leite muda a nutrição.","alcohol_g":5.9},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/sabajon-colombiano/portada.webp"}],[{"language":"es","slug":"torta-negra-colombiana","title":"Torta negra colombiana","seo":{"title":"Torta negra colombiana","description":"Torta negra colombiana con frutas maceradas en vino y melao oscuro de panela. Ponqué navideño de horneado lento, con tiempos y conservación claros.","faq":[{"q":"¿Qué le da el color oscuro?","a":"El melao de panela muy oscuro y las frutas maceradas. No hace falta chocolate; la panela debe caramelizarse sin llegar a quedar negra y amarga."},{"q":"¿Puedo servirla el mismo día?","a":"Sí, una vez fría. Reposar 24 horas en nevera ayuda a que se asienten el sabor y la miga; ese reposo se incluye en los 5 días de conservación."}],"author":"Néstor Bastidas","image_alt":"Torta negra colombiana","additional_time_minutes":3020,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-16x9.webp"]},"summary":"Este ponqué navideño colombiano lleva pasas, ciruelas y naranja confitada maceradas en vino. El melao de panela bien oscuro aporta color y sabor, sin chocolate; la miga queda densa y húmeda.","ingredients":[{"name":"uvas pasas sin semillas","amount":"180","unit":"g"},{"name":"ciruelas pasas sin hueso, picadas","amount":"120","unit":"g"},{"name":"cáscara de naranja confitada, picada","amount":"60","unit":"g"},{"name":"vino tinto dulce al 12 % vol","amount":"200","unit":"ml"},{"name":"panela rallada","amount":"100","unit":"g"},{"name":"agua para caramelizar la panela","amount":"30","unit":"ml"},{"name":"agua hirviendo para diluir el caramelo","amount":"70","unit":"ml"},{"name":"mantequilla sin sal, blanda","amount":"200","unit":"g"},{"name":"azúcar blanca","amount":"120","unit":"g"},{"name":"huevos, unos 4 grandes sin cáscara; pesar 200 g","amount":"200","unit":"g"},{"name":"harina de trigo común","amount":"220","unit":"g"},{"name":"polvo de hornear","amount":"6","unit":"g"},{"name":"canela molida","amount":"3","unit":"g"},{"name":"clavo de olor molido","amount":"0.5","unit":"g"},{"name":"sal","amount":"2","unit":"g"}],"steps":[{"title":"Macera las frutas","content":"Macera las pasas, ciruelas y naranja confitada con los 200 ml de vino en un recipiente tapado durante 48 horas en nevera a 4 °C o menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-01.webp","image_alt":"Macera las frutas"},{"title":"Oscurece la panela","content":"Cocina los 100 g de panela con los 30 ml de agua a fuego medio durante 8–10 minutos, hasta formar un caramelo marrón muy oscuro, sin humo ni zonas negras.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-02.webp","image_alt":"Oscurece la panela"},{"title":"Diluye el caramelo","content":"Fuera del fuego, añade los 70 ml de agua hirviendo poco a poco, con cuchara larga, y disuelve a fuego bajo unos 2 minutos. Este melao se usará frío en el paso 7.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-03.webp","image_alt":"Diluye el caramelo"},{"title":"Bate la mantequilla","content":"Bate los 200 g de mantequilla blanda con los 120 g de azúcar durante 4–5 minutos, hasta que la mezcla esté cremosa.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-04.webp","image_alt":"Bate la mantequilla"},{"title":"Incorpora los huevos","content":"Incorpora los 200 g de huevo poco a poco a la mantequilla, batiendo durante unos 3 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-05.webp","image_alt":"Incorpora los huevos"},{"title":"Añade los secos","content":"Integra los 220 g de harina, los 6 g de polvo de hornear, los 3 g de canela, los 0,5 g de clavo y los 2 g de sal con una espátula, solo hasta desaparecer la harina seca.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-06.webp","image_alt":"Añade los secos"},{"title":"Agrega las frutas","content":"Integra las frutas con todo el vino de maceración y el melao ya frío, hasta obtener una masa oscura y uniforme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-07.webp","image_alt":"Agrega las frutas"},{"title":"Precalienta el horno","content":"Precalienta el horno a 150 °C con calor arriba y abajo, sin ventilador.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-08.webp","image_alt":"Precalienta el horno"},{"title":"Hornea el ponqué","content":"Hornea la masa en un molde redondo de 20 cm de diámetro y 8 cm de alto, previamente engrasado y forrado con papel de horno, durante 90–110 minutos. Está listo cuando el centro está firme y un palillo sale sin masa cruda, con alguna miga húmeda.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-09.webp","image_alt":"Hornea el ponqué"},{"title":"Enfría la torta","content":"Enfría 20 minutos dentro del molde y después unas 2 horas sobre una rejilla, hasta que esté completamente fría. Rinde 12 porciones.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp","image_alt":"Enfría la torta"}],"notes":"<p>El melao debe estar frío antes de añadirlo a la masa; mientras se enfría puedes batir la mantequilla. Al diluir el caramelo, añade el agua despacio para evitar salpicaduras. Conserva la torta fría, bien envuelta o en recipiente hermético, a 4 °C o menos hasta 5 días desde el horneado; sabe mejor tras 24 horas de reposo en nevera. También puedes congelar porciones a −18 °C hasta 2 meses y descongelar en nevera. El horneado no garantiza eliminar todo el alcohol del vino. Contiene trigo, leche y huevo.</p>","category":"Postres","course":"Postres","cuisine":"Colombiana","difficulty":"Intermedia","servings":12,"prep_time_minutes":35,"cook_time_minutes":112,"total_time_minutes":3167,"excerpt":"Este ponqué navideño colombiano lleva pasas, ciruelas y naranja confitada maceradas en vino. El melao de panela bien oscuro aporta color y sabor, sin chocolate; la miga queda densa y húmeda.","content_html":"","keywords":["Torta negra colombiana"],"gallery":[],"public_path":"/torta-negra-colombiana","nutrition":{"calories":380.1,"protein_g":4.8,"carbs_g":55.2,"fat_g":15.4,"serving_size":"1/12","estimated":true,"source":"USDA FoodData Central / Standard Reference; EDEKA candied orange peel label","method":"Suma de nutrientes de ingredientes según las cantidades, dividida entre las raciones.","note":"Por 1 de 12 porciones, sin cobertura. Se cuenta todo el vino sin descontar el alcohol que pueda evaporarse; el vino dulce se aproxima con vino tinto USDA y la panela con azúcar morena. Las marcas de vino y fruta confitada cambian los valores."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp"},{"language":"en","slug":"colombian-black-cake-torta-negra","title":"Colombian Black Cake","seo":{"title":"Colombian Black Cake","description":"Colombian black cake with wine-soaked dried fruit and dark panela caramel. A rich Christmas fruitcake baked slowly, with clear timing and storage tips.","faq":[{"q":"What makes it dark?","a":"Very dark panela caramel and soaked dried fruit. Chocolate is unnecessary; caramelize the panela without burning it black and bitter."},{"q":"Can I serve it the day it is baked?","a":"Yes, once cold. A 24-hour rest in the refrigerator helps the flavor and crumb settle; this rest counts within the 5-day storage period."}],"author":"Néstor Bastidas","image_alt":"Colombian Black Cake","additional_time_minutes":3020,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-16x9.webp"]},"summary":"This Colombian Christmas fruitcake combines wine-soaked raisins, prunes and candied orange peel. Deeply caramelized panela gives it a dark color and rich flavor without chocolate; the crumb is dense and moist.","ingredients":[{"name":"seedless raisins","amount":"180","unit":"g"},{"name":"pitted prunes, chopped","amount":"120","unit":"g"},{"name":"candied orange peel, chopped","amount":"60","unit":"g"},{"name":"sweet red wine, 12% ABV","amount":"200","unit":"ml"},{"name":"grated panela","amount":"100","unit":"g"},{"name":"water for caramelizing the panela","amount":"30","unit":"ml"},{"name":"boiling water for diluting the caramel","amount":"70","unit":"ml"},{"name":"unsalted butter, softened","amount":"200","unit":"g"},{"name":"white sugar","amount":"120","unit":"g"},{"name":"eggs, about 4 large without shells; weigh 200 g","amount":"200","unit":"g"},{"name":"all-purpose wheat flour","amount":"220","unit":"g"},{"name":"baking powder","amount":"6","unit":"g"},{"name":"ground cinnamon","amount":"3","unit":"g"},{"name":"ground cloves","amount":"0.5","unit":"g"},{"name":"salt","amount":"2","unit":"g"}],"steps":[{"title":"Soak the fruit","content":"Soak the raisins, prunes and candied peel in the 200 ml wine in a covered container for 48 hours in the refrigerator at 4 °C or below.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-01.webp","image_alt":"Soak the fruit"},{"title":"Darken the panela","content":"Cook the 100 g panela with the 30 ml water over medium heat for 8–10 minutes to form a very dark brown caramel, without smoke or black patches.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-02.webp","image_alt":"Darken the panela"},{"title":"Dilute the caramel","content":"Off the heat, slowly add the 70 ml boiling water using a long spoon, then dissolve over low heat for about 2 minutes. Use this panela syrup cold in step 7.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-03.webp","image_alt":"Dilute the caramel"},{"title":"Cream the butter","content":"Beat the 200 g soft butter with the 120 g sugar for 4–5 minutes until creamy.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-04.webp","image_alt":"Cream the butter"},{"title":"Beat in the eggs","content":"Gradually beat the 200 g egg into the butter mixture over about 3 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-05.webp","image_alt":"Beat in the eggs"},{"title":"Fold in the dry ingredients","content":"Fold in the 220 g flour, 6 g baking powder, 3 g cinnamon, 0.5 g cloves and 2 g salt with a spatula, just until no dry flour remains.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-06.webp","image_alt":"Fold in the dry ingredients"},{"title":"Add the fruit","content":"Fold in the fruit with all its soaking wine and the cooled panela syrup until the batter is evenly dark.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-07.webp","image_alt":"Add the fruit"},{"title":"Preheat the oven","content":"Preheat a conventional oven to 150 °C with top and bottom heat, fan off.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-08.webp","image_alt":"Preheat the oven"},{"title":"Bake the cake","content":"Bake the batter in a greased, parchment-lined round pan, 20 cm across and 8 cm deep, for 90–110 minutes. The center should feel firm and a skewer should show no raw batter, though a few moist crumbs are fine.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-09.webp","image_alt":"Bake the cake"},{"title":"Cool the cake","content":"Cool in the pan for 20 minutes, then on a rack for about 2 hours until completely cold. Makes 12 slices.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp","image_alt":"Cool the cake"}],"notes":"<p>The panela syrup must be cold before it goes into the batter; cream the butter while it cools. Add the water to the caramel slowly to avoid splashes. Once cold, keep the cake well wrapped or airtight at 4 °C or below for up to 5 days from baking. Its flavor improves after 24 hours in the refrigerator. Freeze slices at −18 °C for up to 2 months and thaw in the refrigerator. Baking does not guarantee that all the wine alcohol disappears. Contains wheat, milk and egg.</p>","category":"Desserts","course":"Desserts","cuisine":"Colombian","difficulty":"Medium","servings":12,"prep_time_minutes":35,"cook_time_minutes":112,"total_time_minutes":3167,"excerpt":"This Colombian Christmas fruitcake combines wine-soaked raisins, prunes and candied orange peel. Deeply caramelized panela gives it a dark color and rich flavor without chocolate; the crumb is dense and moist.","content_html":"","keywords":["Colombian Black Cake"],"gallery":[],"public_path":"/en/colombian-black-cake-torta-negra","nutrition":{"calories":380.1,"protein_g":4.8,"carbs_g":55.2,"fat_g":15.4,"serving_size":"1/12","estimated":true,"source":"USDA FoodData Central / Standard Reference; EDEKA candied orange peel label","method":"Ingredient nutrients summed for the stated quantities and divided by servings.","note":"Per 1 of 12 slices, without frosting. All wine is counted without subtracting alcohol that may evaporate; USDA red wine approximates sweet wine and brown sugar approximates panela. Wine and candied-fruit brands affect the values."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp"},{"language":"de","slug":"kolumbianischer-schwarzer-kuchen","title":"Kolumbianischer schwarzer Kuchen","seo":{"title":"Kolumbianischer schwarzer Kuchen","description":"Kolumbianischer schwarzer Kuchen mit in Wein eingelegten Trockenfrüchten und dunklem Panela-Karamell. Langsam gebacken, mit Zeiten und Aufbewahrungstipps.","faq":[{"q":"Woher kommt die dunkle Farbe?","a":"Von sehr dunklem Panela-Karamell und eingelegten Trockenfrüchten. Schokolade ist nicht nötig; die Panela darf nicht schwarz und bitter verbrennen."},{"q":"Kann ich ihn am Backtag servieren?","a":"Ja, sobald er kalt ist. 24 Stunden im Kühlschrank lassen Geschmack und Krume ruhen; sie zählen zu den 5 Tagen Lagerzeit."}],"author":"Néstor Bastidas","image_alt":"Kolumbianischer schwarzer Kuchen","additional_time_minutes":3020,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-16x9.webp"]},"summary":"Dieser kolumbianische Weihnachtskuchen enthält in Wein eingelegte Rosinen, Pflaumen und kandierte Orangenschale. Dunkles Panela-Karamell sorgt ohne Schokolade für Farbe und Aroma; die Krume bleibt dicht und saftig.","ingredients":[{"name":"kernlose Rosinen","amount":"180","unit":"g"},{"name":"entsteinte Trockenpflaumen, gehackt","amount":"120","unit":"g"},{"name":"kandierte Orangenschale, gehackt","amount":"60","unit":"g"},{"name":"süßer Rotwein mit 12 % vol","amount":"200","unit":"ml"},{"name":"geriebene Panela","amount":"100","unit":"g"},{"name":"Wasser zum Karamellisieren der Panela","amount":"30","unit":"ml"},{"name":"kochendes Wasser zum Verdünnen des Karamells","amount":"70","unit":"ml"},{"name":"ungesalzene Butter, weich","amount":"200","unit":"g"},{"name":"weißer Zucker","amount":"120","unit":"g"},{"name":"Eier, etwa 4 große ohne Schale; 200 g abwiegen","amount":"200","unit":"g"},{"name":"Weizenmehl Type 405","amount":"220","unit":"g"},{"name":"Backpulver","amount":"6","unit":"g"},{"name":"gemahlener Zimt","amount":"3","unit":"g"},{"name":"gemahlene Gewürznelken","amount":"0.5","unit":"g"},{"name":"Salz","amount":"2","unit":"g"}],"steps":[{"title":"Früchte einlegen","content":"Rosinen, Pflaumen und Orangenschale mit den 200 ml Wein in einem verschlossenen Gefäß 48 Stunden bei höchstens 4 °C im Kühlschrank einlegen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-01.webp","image_alt":"Früchte einlegen"},{"title":"Panela karamellisieren","content":"Die 100 g Panela mit den 30 ml Wasser bei mittlerer Hitze 8–10 Minuten zu sehr dunkelbraunem Karamell kochen, ohne Rauch oder schwarze Stellen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-02.webp","image_alt":"Panela karamellisieren"},{"title":"Karamell verdünnen","content":"Abseits des Herds die 70 ml kochendes Wasser mit einem langen Löffel langsam zugeben und bei kleiner Hitze etwa 2 Minuten auflösen. Den Sirup in Schritt 7 kalt verwenden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-03.webp","image_alt":"Karamell verdünnen"},{"title":"Butter cremig schlagen","content":"Die 200 g weiche Butter mit den 120 g Zucker 4–5 Minuten cremig schlagen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-04.webp","image_alt":"Butter cremig schlagen"},{"title":"Eier einarbeiten","content":"Die 200 g Ei nach und nach etwa 3 Minuten unter die Buttermasse schlagen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-05.webp","image_alt":"Eier einarbeiten"},{"title":"Trockene Zutaten unterheben","content":"Die 220 g Mehl, 6 g Backpulver, 3 g Zimt, 0,5 g Nelken und 2 g Salz mit einem Teigschaber unterheben, bis kein trockenes Mehl mehr sichtbar ist.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-06.webp","image_alt":"Trockene Zutaten unterheben"},{"title":"Früchte zugeben","content":"Die Früchte samt dem gesamten Einlegewein und den kalten Panela-Sirup unterheben, bis der Teig gleichmäßig dunkel ist.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-07.webp","image_alt":"Früchte zugeben"},{"title":"Ofen vorheizen","content":"Den Backofen auf 150 °C Ober-/Unterhitze ohne Umluft vorheizen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-08.webp","image_alt":"Ofen vorheizen"},{"title":"Kuchen backen","content":"Den Teig in einer gefetteten, mit Backpapier ausgelegten runden Form von 20 cm Durchmesser und 8 cm Höhe 90–110 Minuten backen. Die Mitte muss fest sein; am Holzstäbchen dürfen feuchte Krümel, aber kein roher Teig haften.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-09.webp","image_alt":"Kuchen backen"},{"title":"Kuchen auskühlen","content":"20 Minuten in der Form, dann etwa 2 Stunden auf einem Gitter vollständig auskühlen lassen. Ergibt 12 Stücke.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp","image_alt":"Kuchen auskühlen"}],"notes":"<p>Der Panela-Sirup muss vor dem Unterheben kalt sein; währenddessen lässt sich die Butter aufschlagen. Das Wasser langsam zum Karamell geben, damit es nicht spritzt. Den kalten Kuchen gut eingewickelt oder luftdicht bei höchstens 4 °C bis zu 5 Tage ab Backtag lagern. Nach 24 Stunden im Kühlschrank schmeckt er noch runder. Stücke bei −18 °C bis zu 2 Monate einfrieren und im Kühlschrank auftauen. Beim Backen verschwindet der Weinalkohol nicht garantiert vollständig. Enthält Weizen, Milch und Ei.</p>","category":"Desserts","course":"Desserts","cuisine":"Kolumbianisch","difficulty":"Mittel","servings":12,"prep_time_minutes":35,"cook_time_minutes":112,"total_time_minutes":3167,"excerpt":"Dieser kolumbianische Weihnachtskuchen enthält in Wein eingelegte Rosinen, Pflaumen und kandierte Orangenschale. Dunkles Panela-Karamell sorgt ohne Schokolade für Farbe und Aroma; die Krume bleibt dicht und saftig.","content_html":"","keywords":["Kolumbianischer schwarzer Kuchen"],"gallery":[],"public_path":"/de/kolumbianischer-schwarzer-kuchen","nutrition":{"calories":380.1,"protein_g":4.8,"carbs_g":55.2,"fat_g":15.4,"serving_size":"1/12","estimated":true,"source":"USDA FoodData Central / Standard Reference; EDEKA candied orange peel label","method":"Nährstoffe der angegebenen Zutatenmengen addiert und durch die Portionen geteilt.","note":"Für 1 von 12 Stücken, ohne Glasur. Der gesamte Wein ist ohne Abzug verdampften Alkohols berechnet; USDA-Rotwein nähert Süßwein an, brauner Zucker Panela. Wein- und Orangeatmarke beeinflussen die Werte."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp"},{"language":"fr","slug":"gateau-noir-colombien","title":"Gâteau noir colombien","seo":{"title":"Gâteau noir colombien","description":"Gâteau noir colombien aux fruits secs macérés dans le vin et au caramel de panela. Un gâteau de Noël cuit lentement, avec repères de cuisson et conservation.","faq":[{"q":"D’où vient la couleur foncée ?","a":"Du caramel très foncé de panela et des fruits macérés. Le chocolat n’est pas nécessaire ; évitez une panela brûlée, noire et amère."},{"q":"Peut-on le servir le jour même ?","a":"Oui, une fois froid. Un repos de 24 heures au réfrigérateur harmonise la saveur et la mie ; il fait partie des 5 jours de conservation."}],"author":"Néstor Bastidas","image_alt":"Gâteau noir colombien","additional_time_minutes":3020,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-16x9.webp"]},"summary":"Ce gâteau de Noël colombien réunit raisins secs, pruneaux et écorces d’orange confites macérés dans le vin. Le caramel foncé de panela apporte couleur et caractère, sans chocolat, à une mie dense et moelleuse.","ingredients":[{"name":"raisins secs sans pépins","amount":"180","unit":"g"},{"name":"pruneaux dénoyautés, hachés","amount":"120","unit":"g"},{"name":"écorces d’orange confites, hachées","amount":"60","unit":"g"},{"name":"vin rouge doux à 12 % vol","amount":"200","unit":"ml"},{"name":"panela râpée","amount":"100","unit":"g"},{"name":"eau pour caraméliser la panela","amount":"30","unit":"ml"},{"name":"eau bouillante pour diluer le caramel","amount":"70","unit":"ml"},{"name":"beurre doux, mou","amount":"200","unit":"g"},{"name":"sucre blanc","amount":"120","unit":"g"},{"name":"œufs, environ 4 gros sans coquille ; peser 200 g","amount":"200","unit":"g"},{"name":"farine de blé T55","amount":"220","unit":"g"},{"name":"levure chimique","amount":"6","unit":"g"},{"name":"cannelle moulue","amount":"3","unit":"g"},{"name":"clou de girofle moulu","amount":"0.5","unit":"g"},{"name":"sel","amount":"2","unit":"g"}],"steps":[{"title":"Macérez les fruits","content":"Faites macérer raisins, pruneaux et orange dans les 200 ml de vin, dans un récipient fermé, 48 heures au réfrigérateur à 4 °C ou moins.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-01.webp","image_alt":"Macérez les fruits"},{"title":"Caramélisez la panela","content":"Cuisez les 100 g de panela avec les 30 ml d’eau à feu moyen 8–10 minutes, jusqu’à un caramel brun très foncé, sans fumée ni zones noires.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-02.webp","image_alt":"Caramélisez la panela"},{"title":"Diluez le caramel","content":"Hors du feu, ajoutez lentement les 70 ml d’eau bouillante avec une longue cuillère, puis dissolvez à feu doux environ 2 minutes. Ce sirop s’utilise froid à l’étape 7.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-03.webp","image_alt":"Diluez le caramel"},{"title":"Crémez le beurre","content":"Battez les 200 g de beurre mou avec les 120 g de sucre pendant 4–5 minutes pour obtenir une texture crémeuse.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-04.webp","image_alt":"Crémez le beurre"},{"title":"Incorporez les œufs","content":"Incorporez progressivement les 200 g d’œuf au beurre en battant environ 3 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-05.webp","image_alt":"Incorporez les œufs"},{"title":"Ajoutez les poudres","content":"Incorporez à la spatule les 220 g de farine, 6 g de levure, 3 g de cannelle, 0,5 g de girofle et 2 g de sel, juste pour faire disparaître la farine sèche.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-06.webp","image_alt":"Ajoutez les poudres"},{"title":"Ajoutez les fruits","content":"Incorporez les fruits avec tout le vin de macération et le sirop de panela froid, jusqu’à une pâte uniformément foncée.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-07.webp","image_alt":"Ajoutez les fruits"},{"title":"Préchauffez le four","content":"Préchauffez le four à 150 °C en chaleur traditionnelle, sans ventilation.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-08.webp","image_alt":"Préchauffez le four"},{"title":"Cuisez le gâteau","content":"Cuisez la pâte dans un moule rond de 20 cm de diamètre et 8 cm de haut, beurré et chemisé de papier cuisson, pendant 90–110 minutes. Le centre doit être ferme et une pique ressortir sans pâte crue, avec quelques miettes humides possibles.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-09.webp","image_alt":"Cuisez le gâteau"},{"title":"Laissez refroidir","content":"Laissez refroidir 20 minutes dans le moule, puis environ 2 heures sur une grille, jusqu’à complet refroidissement. Donne 12 parts.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp","image_alt":"Laissez refroidir"}],"notes":"<p>Le sirop de panela doit être froid avant de rejoindre la pâte ; profitez de son refroidissement pour battre le beurre. Versez l’eau lentement dans le caramel pour limiter les projections. Gardez le gâteau froid bien emballé ou dans une boîte hermétique à 4 °C ou moins jusqu’à 5 jours après cuisson. Il gagne en saveur après 24 heures au réfrigérateur. Les parts se congèlent à −18 °C jusqu’à 2 mois ; décongelez au réfrigérateur. La cuisson ne garantit pas l’élimination totale de l’alcool du vin. Contient blé, lait et œuf.</p>","category":"Desserts","course":"Desserts","cuisine":"Colombienne","difficulty":"Intermédiaire","servings":12,"prep_time_minutes":35,"cook_time_minutes":112,"total_time_minutes":3167,"excerpt":"Ce gâteau de Noël colombien réunit raisins secs, pruneaux et écorces d’orange confites macérés dans le vin. Le caramel foncé de panela apporte couleur et caractère, sans chocolat, à une mie dense et moelleuse.","content_html":"","keywords":["Gâteau noir colombien"],"gallery":[],"public_path":"/fr/gateau-noir-colombien","nutrition":{"calories":380.1,"protein_g":4.8,"carbs_g":55.2,"fat_g":15.4,"serving_size":"1/12","estimated":true,"source":"USDA FoodData Central / Standard Reference; EDEKA candied orange peel label","method":"Somme des nutriments des quantités indiquées, divisée par le nombre de portions.","note":"Pour 1 part sur 12, sans glaçage. Tout le vin est compté sans déduire l’alcool pouvant s’évaporer ; le vin rouge USDA sert d’équivalent au vin doux et le sucre brun à la panela. Les marques de vin et fruits confits changent les valeurs."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp"},{"language":"it","slug":"torta-nera-colombiana","title":"Torta nera colombiana","seo":{"title":"Torta nera colombiana","description":"Torta nera colombiana con frutta secca macerata nel vino e caramello scuro di panela. Dolce natalizio a cottura lenta, con tempi e consigli di conservazione.","faq":[{"q":"Da cosa viene il colore scuro?","a":"Dal caramello molto scuro di panela e dalla frutta macerata. Non serve cioccolato; la panela non deve bruciare diventando nera e amara."},{"q":"Posso servirla il giorno stesso?","a":"Sì, quando è fredda. Un riposo di 24 ore in frigorifero armonizza sapore e consistenza; conta nei 5 giorni di conservazione."}],"author":"Néstor Bastidas","image_alt":"Torta nera colombiana","additional_time_minutes":3020,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-16x9.webp"]},"summary":"Questo dolce natalizio colombiano racchiude uvetta, prugne e scorza d’arancia candita macerate nel vino. Il caramello scuro di panela dona colore e sapore senza cioccolato; la consistenza è compatta e umida.","ingredients":[{"name":"uvetta senza semi","amount":"180","unit":"g"},{"name":"prugne secche denocciolate, tritate","amount":"120","unit":"g"},{"name":"scorza d’arancia candita, tritata","amount":"60","unit":"g"},{"name":"vino rosso dolce al 12% vol","amount":"200","unit":"ml"},{"name":"panela grattugiata","amount":"100","unit":"g"},{"name":"acqua per caramellare la panela","amount":"30","unit":"ml"},{"name":"acqua bollente per diluire il caramello","amount":"70","unit":"ml"},{"name":"burro non salato, morbido","amount":"200","unit":"g"},{"name":"zucchero bianco","amount":"120","unit":"g"},{"name":"uova, circa 4 grandi senza guscio; pesarne 200 g","amount":"200","unit":"g"},{"name":"farina di grano tenero 00","amount":"220","unit":"g"},{"name":"lievito per dolci","amount":"6","unit":"g"},{"name":"cannella in polvere","amount":"3","unit":"g"},{"name":"chiodi di garofano macinati","amount":"0.5","unit":"g"},{"name":"sale","amount":"2","unit":"g"}],"steps":[{"title":"Macera la frutta","content":"Macera uvetta, prugne e arancia con i 200 ml di vino in un recipiente chiuso per 48 ore in frigorifero a 4 °C o meno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-01.webp","image_alt":"Macera la frutta"},{"title":"Caramella la panela","content":"Cuoci i 100 g di panela con i 30 ml d’acqua a fuoco medio per 8–10 minuti, fino a un caramello marrone molto scuro, senza fumo né parti nere.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-02.webp","image_alt":"Caramella la panela"},{"title":"Diluisci il caramello","content":"Fuori dal fuoco, aggiungi lentamente i 70 ml d’acqua bollente con un cucchiaio lungo e sciogli a fuoco basso per circa 2 minuti. Usa questo sciroppo freddo al passaggio 7.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-03.webp","image_alt":"Diluisci il caramello"},{"title":"Monta il burro","content":"Monta i 200 g di burro morbido con i 120 g di zucchero per 4–5 minuti, fino a renderli cremosi.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-04.webp","image_alt":"Monta il burro"},{"title":"Incorpora le uova","content":"Incorpora poco alla volta i 200 g d’uovo al burro, sbattendo per circa 3 minuti.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-05.webp","image_alt":"Incorpora le uova"},{"title":"Unisci le polveri","content":"Incorpora con una spatola i 220 g di farina, 6 g di lievito, 3 g di cannella, 0,5 g di chiodi di garofano e 2 g di sale, solo finché non resta farina asciutta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-06.webp","image_alt":"Unisci le polveri"},{"title":"Aggiungi la frutta","content":"Incorpora la frutta con tutto il vino di macerazione e lo sciroppo di panela freddo, fino a ottenere un impasto scuro uniforme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-07.webp","image_alt":"Aggiungi la frutta"},{"title":"Scalda il forno","content":"Preriscalda il forno statico a 150 °C, senza ventilazione.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-08.webp","image_alt":"Scalda il forno"},{"title":"Cuoci la torta","content":"Cuoci l’impasto in uno stampo rotondo di 20 cm di diametro e 8 cm d’altezza, imburrato e rivestito di carta forno, per 90–110 minuti. Il centro deve essere fermo e lo stecchino uscire senza impasto crudo; qualche briciola umida va bene.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-09.webp","image_alt":"Cuoci la torta"},{"title":"Fai raffreddare","content":"Lascia raffreddare 20 minuti nello stampo, poi circa 2 ore su una gratella fino a completo raffreddamento. Ottieni 12 fette.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp","image_alt":"Fai raffreddare"}],"notes":"<p>Lo sciroppo di panela deve essere freddo prima di entrare nell’impasto; nel frattempo puoi montare il burro. Aggiungi l’acqua al caramello lentamente per evitare schizzi. Conserva la torta fredda ben avvolta o in un contenitore ermetico a 4 °C o meno per un massimo di 5 giorni dalla cottura. È più saporita dopo 24 ore in frigorifero. Puoi congelare le fette a −18 °C fino a 2 mesi e scongelarle in frigorifero. La cottura non garantisce di eliminare tutto l’alcol del vino. Contiene grano, latte e uova.</p>","category":"Dolci","course":"Dolci","cuisine":"Colombiana","difficulty":"Media","servings":12,"prep_time_minutes":35,"cook_time_minutes":112,"total_time_minutes":3167,"excerpt":"Questo dolce natalizio colombiano racchiude uvetta, prugne e scorza d’arancia candita macerate nel vino. Il caramello scuro di panela dona colore e sapore senza cioccolato; la consistenza è compatta e umida.","content_html":"","keywords":["Torta nera colombiana"],"gallery":[],"public_path":"/it/torta-nera-colombiana","nutrition":{"calories":380.1,"protein_g":4.8,"carbs_g":55.2,"fat_g":15.4,"serving_size":"1/12","estimated":true,"source":"USDA FoodData Central / Standard Reference; EDEKA candied orange peel label","method":"Somma dei nutrienti delle quantità indicate divisa per il numero di porzioni.","note":"Per 1 delle 12 fette, senza glassa. È conteggiato tutto il vino senza sottrarre l’alcol che può evaporare; vino rosso USDA e zucchero di canna approssimano vino dolce e panela. Le marche di vino e canditi cambiano i valori."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp"},{"language":"ja","slug":"colombia-torta-negra","title":"コロンビアのトルタ・ネグラ","seo":{"title":"コロンビアのトルタ・ネグラ","description":"コロンビアのクリスマス菓子、トルタ・ネグラ。赤ワインに漬けたレーズンやプルーンと、濃く色づけたパネラのカラメルで作る黒いフルーツケーキです。150 °Cでじっくり焼く時間、中心まで焼けた目安、冷ます手順、冷蔵と冷凍の保存期間も丁寧に紹介します。","faq":[{"q":"黒い色は何からつきますか？","a":"濃いパネラのカラメルと漬けたドライフルーツの色です。チョコレートは不要。パネラを黒く苦くなるまで焦がさないでください。"},{"q":"焼いた日に食べられますか？","a":"完全に冷めれば食べられます。冷蔵で24時間休ませると味と生地がなじみますが、この時間も保存期間5日以内に含めます。"}],"author":"Néstor Bastidas","image_alt":"コロンビアのトルタ・ネグラ","additional_time_minutes":3020,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-16x9.webp"]},"summary":"ワインに漬けたレーズン、プルーン、オレンジピールを焼き込むコロンビアのクリスマスケーキ。濃いパネラのカラメルで色とコクをつけ、チョコレートは使いません。しっとりと密度のある生地が特徴です。","ingredients":[{"name":"種なしレーズン","amount":"180","unit":"g"},{"name":"種を除いたプルーン（刻んだもの）","amount":"120","unit":"g"},{"name":"砂糖漬けオレンジピール（刻んだもの）","amount":"60","unit":"g"},{"name":"甘口赤ワイン（アルコール度数12%）","amount":"200","unit":"ml"},{"name":"細かくしたパネラ","amount":"100","unit":"g"},{"name":"パネラをカラメルにするための水","amount":"30","unit":"ml"},{"name":"カラメルを溶かすための熱湯","amount":"70","unit":"ml"},{"name":"無塩バター（やわらかくしたもの）","amount":"200","unit":"g"},{"name":"グラニュー糖","amount":"120","unit":"g"},{"name":"全卵（大きめ約4個分、殻なしで200 gを量る）","amount":"200","unit":"g"},{"name":"薄力粉","amount":"220","unit":"g"},{"name":"ベーキングパウダー","amount":"6","unit":"g"},{"name":"シナモンパウダー","amount":"3","unit":"g"},{"name":"クローブパウダー","amount":"0.5","unit":"g"},{"name":"塩","amount":"2","unit":"g"}],"steps":[{"title":"果物を漬ける","content":"レーズン、プルーン、オレンジピールをワイン200 mlに漬け、ふた付き容器で4 °C以下の冷蔵庫に48時間置きます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-01.webp","image_alt":"果物を漬ける"},{"title":"パネラを色づける","content":"パネラ100 gと水30 mlを中火で8～10分煮て、濃いこげ茶色のカラメルにします。煙を出したり黒く焦がしたりしません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-02.webp","image_alt":"パネラを色づける"},{"title":"カラメルを溶かす","content":"火から外して熱湯70 mlを長いスプーンで少しずつ加え、弱火で約2分溶かします。このシロップは手順7で冷めた状態で使います。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-03.webp","image_alt":"カラメルを溶かす"},{"title":"バターを混ぜる","content":"やわらかいバター200 gと砂糖120 gを4～5分泡立て、クリーム状にします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-04.webp","image_alt":"バターを混ぜる"},{"title":"卵を加える","content":"全卵200 gをバターの生地に少しずつ加え、約3分混ぜます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-05.webp","image_alt":"卵を加える"},{"title":"粉類を合わせる","content":"薄力粉220 g、ベーキングパウダー6 g、シナモン3 g、クローブ0.5 g、塩2 gをへらで加え、粉が見えなくなるまで混ぜます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-06.webp","image_alt":"粉類を合わせる"},{"title":"果物を加える","content":"果物を漬けたワイン全量と冷めたパネラのシロップを加え、色が均一になるまで混ぜます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-07.webp","image_alt":"果物を加える"},{"title":"オーブンを予熱する","content":"オーブンを150 °Cに予熱します。上下加熱で、ファンは使いません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-08.webp","image_alt":"オーブンを予熱する"},{"title":"ケーキを焼く","content":"油脂を塗ってオーブンペーパーを敷いた直径20 cm、高さ8 cmの丸型で90～110分焼きます。中心が固まり、竹串に生の生地がつかなければ焼き上がり。湿った細かいくずはついてもかまいません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-09.webp","image_alt":"ケーキを焼く"},{"title":"ケーキを冷ます","content":"型の中で20分、その後は網の上で約2時間、完全に冷まします。12切れ分です。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp","image_alt":"ケーキを冷ます"}],"notes":"<p>パネラのシロップは冷めてから生地に加えます。冷める間にバターを混ぜるとスムーズです。熱いカラメルに水を入れるときは、はねないように少しずつ加えてください。冷めたケーキはしっかり包むか密閉し、4 °C以下で焼いた日から5日以内に食べ切ります。冷蔵庫で24時間休ませると味がなじみます。切り分けて−18 °Cで2か月まで冷凍でき、解凍は冷蔵庫で行います。焼いてもワインのアルコールが完全になくなるとは限りません。小麦・乳・卵を含みます。</p>","category":"デザート","course":"デザート","cuisine":"コロンビア料理","difficulty":"中級","servings":12,"prep_time_minutes":35,"cook_time_minutes":112,"total_time_minutes":3167,"excerpt":"ワインに漬けたレーズン、プルーン、オレンジピールを焼き込むコロンビアのクリスマスケーキ。濃いパネラのカラメルで色とコクをつけ、チョコレートは使いません。しっとりと密度のある生地が特徴です。","content_html":"","keywords":["コロンビアのトルタ・ネグラ"],"gallery":[],"public_path":"/ja/colombia-torta-negra","nutrition":{"calories":380.1,"protein_g":4.8,"carbs_g":55.2,"fat_g":15.4,"serving_size":"1/12","estimated":true,"source":"USDA FoodData Central / Standard Reference; EDEKA candied orange peel label","method":"材料の分量から栄養を合計し、人数分で割った推定値です。","note":"12等分の1切れ分。アイシングなし。蒸発する可能性のあるアルコールも差し引かず、ワイン全量を計算。甘口ワインはUSDAの赤ワイン、パネラはブラウンシュガーで近似しています。ワインやピールの製品によって値は変わります。"},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp"},{"language":"pt","slug":"bolo-preto-colombiano","title":"Bolo preto colombiano","seo":{"title":"Bolo preto colombiano","description":"Bolo preto colombiano com frutas secas maceradas no vinho e caramelo escuro de panela. Receita natalina de forno baixo, com tempos e conservação explicados.","faq":[{"q":"De onde vem a cor escura?","a":"Do caramelo bem escuro de panela e das frutas maceradas. Não precisa de chocolate; a panela não deve queimar até ficar preta e amarga."},{"q":"Posso servir no mesmo dia?","a":"Sim, depois de esfriar. Descansar 24 horas na geladeira ajuda a firmar sabor e textura; esse descanso conta nos 5 dias de conservação."}],"author":"Néstor Bastidas","image_alt":"Bolo preto colombiano","additional_time_minutes":3020,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada-16x9.webp"]},"summary":"Este bolo de Natal colombiano leva passas, ameixas e casca de laranja cristalizada maceradas no vinho. O caramelo bem escuro de panela dá cor e sabor sem chocolate; a massa fica densa e úmida.","ingredients":[{"name":"uvas-passas sem sementes","amount":"180","unit":"g"},{"name":"ameixas secas sem caroço, picadas","amount":"120","unit":"g"},{"name":"casca de laranja cristalizada, picada","amount":"60","unit":"g"},{"name":"vinho tinto doce a 12% vol","amount":"200","unit":"ml"},{"name":"panela ralada","amount":"100","unit":"g"},{"name":"água para caramelizar a panela","amount":"30","unit":"ml"},{"name":"água fervente para diluir o caramelo","amount":"70","unit":"ml"},{"name":"manteiga sem sal, macia","amount":"200","unit":"g"},{"name":"açúcar branco","amount":"120","unit":"g"},{"name":"ovos, cerca de 4 grandes sem casca; pesar 200 g","amount":"200","unit":"g"},{"name":"farinha de trigo comum","amount":"220","unit":"g"},{"name":"fermento químico em pó","amount":"6","unit":"g"},{"name":"canela em pó","amount":"3","unit":"g"},{"name":"cravo-da-índia moído","amount":"0.5","unit":"g"},{"name":"sal","amount":"2","unit":"g"}],"steps":[{"title":"Macere as frutas","content":"Macere passas, ameixas e laranja com os 200 ml de vinho num recipiente tampado por 48 horas na geladeira a 4 °C ou menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-01.webp","image_alt":"Macere as frutas"},{"title":"Caramelize a panela","content":"Cozinhe os 100 g de panela com os 30 ml de água em fogo médio por 8–10 minutos, até um caramelo marrom bem escuro, sem fumaça nem partes pretas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-02.webp","image_alt":"Caramelize a panela"},{"title":"Dilua o caramelo","content":"Fora do fogo, acrescente lentamente os 70 ml de água fervente com uma colher longa e dissolva em fogo baixo por cerca de 2 minutos. Use essa calda fria no passo 7.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-03.webp","image_alt":"Dilua o caramelo"},{"title":"Bata a manteiga","content":"Bata os 200 g de manteiga macia com os 120 g de açúcar por 4–5 minutos, até ficar cremoso.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-04.webp","image_alt":"Bata a manteiga"},{"title":"Incorpore os ovos","content":"Incorpore aos poucos os 200 g de ovo à manteiga, batendo por cerca de 3 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-05.webp","image_alt":"Incorpore os ovos"},{"title":"Junte os secos","content":"Incorpore com uma espátula os 220 g de farinha, 6 g de fermento, 3 g de canela, 0,5 g de cravo e 2 g de sal, apenas até não haver farinha seca.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-06.webp","image_alt":"Junte os secos"},{"title":"Adicione as frutas","content":"Incorpore as frutas com todo o vinho da maceração e a calda de panela fria, até obter uma massa escura uniforme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-07.webp","image_alt":"Adicione as frutas"},{"title":"Preaqueça o forno","content":"Preaqueça o forno a 150 °C, com calor em cima e embaixo, sem ventilação.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-08.webp","image_alt":"Preaqueça o forno"},{"title":"Asse o bolo","content":"Asse a massa numa forma redonda de 20 cm de diâmetro e 8 cm de altura, untada e forrada com papel-manteiga, por 90–110 minutos. O centro deve estar firme e o palito sair sem massa crua; algumas migalhas úmidas são normais.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/paso-09.webp","image_alt":"Asse o bolo"},{"title":"Esfrie o bolo","content":"Deixe esfriar 20 minutos na forma e depois cerca de 2 horas numa grade, até esfriar completamente. Rende 12 fatias.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp","image_alt":"Esfrie o bolo"}],"notes":"<p>A calda de panela deve estar fria antes de entrar na massa; enquanto esfria, você pode bater a manteiga. Adicione a água ao caramelo lentamente para evitar respingos. Guarde o bolo frio bem embalado ou num recipiente hermético a 4 °C ou menos por até 5 dias após assar. O sabor melhora após 24 horas na geladeira. Congele fatias a −18 °C por até 2 meses e descongele na geladeira. Assar não garante eliminar todo o álcool do vinho. Contém trigo, leite e ovo.</p>","category":"Sobremesas","course":"Sobremesas","cuisine":"Colombiana","difficulty":"Média","servings":12,"prep_time_minutes":35,"cook_time_minutes":112,"total_time_minutes":3167,"excerpt":"Este bolo de Natal colombiano leva passas, ameixas e casca de laranja cristalizada maceradas no vinho. O caramelo bem escuro de panela dá cor e sabor sem chocolate; a massa fica densa e úmida.","content_html":"","keywords":["Bolo preto colombiano"],"gallery":[],"public_path":"/pt/bolo-preto-colombiano","nutrition":{"calories":380.1,"protein_g":4.8,"carbs_g":55.2,"fat_g":15.4,"serving_size":"1/12","estimated":true,"source":"USDA FoodData Central / Standard Reference; EDEKA candied orange peel label","method":"Soma dos nutrientes das quantidades indicadas dividida pelo número de porções.","note":"Por 1 das 12 fatias, sem cobertura. Todo o vinho entra no cálculo, sem descontar álcool que possa evaporar; vinho tinto USDA e açúcar mascavo aproximam vinho doce e panela. As marcas de vinho e frutas cristalizadas mudam os valores."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/torta-negra-colombiana/portada.webp"}],[{"language":"es","slug":"dulce-de-papaya-verde","title":"Dulce de papaya verde","seo":{"title":"Dulce de papaya verde","description":"Dulce de papaya verde en tiras con almíbar de panela, canela y clavo. Postre colombiano de diciembre, con tiempos claros y conservación en nevera.","faq":[{"q":"¿Cómo sé que está lista?","a":"Las tiras deben estar translúcidas, tiernas al pincharlas y conservar su forma. El almíbar debe cubrir ligeramente una cuchara."},{"q":"¿Sirve la papaya madura?","a":"No para esta textura. La papaya verde firme aguanta la cocción larga; la madura puede deshacerse."}],"author":"Néstor Bastidas","image_alt":"Dulce de papaya verde","additional_time_minutes":360,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-16x9.webp"]},"summary":"La papaya verde firme se transforma en tiras tiernas y translúcidas al cocinarla en almíbar de panela con canela y clavo. Un dulce casero colombiano de diciembre que conserva la forma de la fruta.","ingredients":[{"name":"papaya verde firme, pelada y sin semillas; peso limpio","amount":"1000","unit":"g"},{"name":"panela rallada","amount":"450","unit":"g"},{"name":"agua para remojar","amount":"2000","unit":"ml"},{"name":"agua para la primera cocción","amount":"2000","unit":"ml"},{"name":"agua para el almíbar","amount":"750","unit":"ml"},{"name":"canela en rama, unos 3 g","amount":"1","unit":"unidad"},{"name":"clavos de olor enteros, unos 0,8 g","amount":"4","unit":"unidad"}],"steps":[{"title":"Corta la papaya","content":"Corta los 1000 g de papaya limpia en tiras de aproximadamente 1 × 1 × 6 cm, de grosor uniforme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-01.webp","image_alt":"Corta la papaya"},{"title":"Remoja las tiras","content":"Remoja las tiras en los 2000 ml de agua fría durante 1 hora en nevera a 4 °C o menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-02.webp","image_alt":"Remoja las tiras"},{"title":"Enjuaga la papaya","content":"Enjuaga las tiras con agua limpia para retirar restos de látex; deben quedar bien escurridas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-03.webp","image_alt":"Enjuaga la papaya"},{"title":"Ablanda la fruta","content":"Cocina las tiras en los otros 2000 ml de agua a hervor suave durante 10–15 minutos, hasta que estén flexibles y un palillo entre fácilmente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-04.webp","image_alt":"Ablanda la fruta"},{"title":"Prepara el almíbar","content":"Disuelve los 450 g de panela en los 750 ml de agua con la rama de canela y los 4 clavos, a fuego bajo durante unos 10 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-05.webp","image_alt":"Prepara el almíbar"},{"title":"Cala la papaya","content":"Cocina la papaya cocida y escurrida en el almíbar, destapada y a fuego bajo, durante 45–60 minutos. Está lista cuando las tiras se ven translúcidas y tiernas y el almíbar cubre ligeramente una cuchara.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-06.webp","image_alt":"Cala la papaya"},{"title":"Retira las especias","content":"Retira la rama de canela y los 4 clavos al terminar la cocción.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-07.webp","image_alt":"Retira las especias"},{"title":"Enfría el dulce","content":"Enfría la papaya con su almíbar en un recipiente bajo durante un máximo de 1 hora. No debe pasar más de 2 horas en total fuera de la nevera.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-08.webp","image_alt":"Enfría el dulce"},{"title":"Refrigera","content":"Refrigera el recipiente tapado durante al menos 4 horas a 4 °C o menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-09.webp","image_alt":"Refrigera"},{"title":"Sirve","content":"Reparte la papaya y todo su almíbar en 10 porciones. Sírvela fría o ligeramente fresca.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp","image_alt":"Sirve"}],"notes":"<p>Usa papaya verdaderamente verde, de pulpa firme y clara, no papaya madura de pulpa naranja. La receta se cocina en el fogón: el agua hierve cerca de 100 °C al nivel del mar, a menor temperatura en altura; guía el punto por la textura. Conserva tapada en su almíbar a 4 °C o menos durante un máximo de 5 días desde la preparación. Es un dulce refrigerado, no una conserva para guardar a temperatura ambiente. Si el almíbar espesa antes de ablandarse la fruta, añade agua caliente poco a poco.</p>","category":"Postres","course":"Postres","cuisine":"Colombiana","difficulty":"Intermedia","servings":10,"prep_time_minutes":25,"cook_time_minutes":80,"total_time_minutes":465,"excerpt":"La papaya verde firme se transforma en tiras tiernas y translúcidas al cocinarla en almíbar de panela con canela y clavo. Un dulce casero colombiano de diciembre que conserva la forma de la fruta.","content_html":"","keywords":["Dulce de papaya verde"],"gallery":[],"public_path":"/dulce-de-papaya-verde","nutrition":{"calories":214.0,"protein_g":0.5,"carbs_g":55.0,"fat_g":0.3,"serving_size":"1/10","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Suma de nutrientes de ingredientes según las cantidades, dividida entre las raciones.","note":"Por 1 de 10 porciones, con una décima parte de todo el almíbar, sin acompañamientos. Se usa papaya cruda genérica como aproximación de la verde y azúcar morena para la panela; no incluye las especias retiradas. Dejar almíbar reduce el azúcar consumido."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp"},{"language":"en","slug":"colombian-green-papaya-dessert","title":"Colombian Green Papaya Dessert","seo":{"title":"Colombian Green Papaya Dessert","description":"Green papaya strips in panela syrup with cinnamon and cloves. A Colombian Christmas dessert with clear cooking times, doneness cues and refrigerator storage.","faq":[{"q":"How do I know it is ready?","a":"The strips should be translucent and tender when pierced, yet hold their shape. The syrup should lightly coat a spoon."},{"q":"Can I use ripe papaya?","a":"Not for this texture. Firm green papaya stands up to long cooking; ripe fruit may fall apart."}],"author":"Néstor Bastidas","image_alt":"Colombian Green Papaya Dessert","additional_time_minutes":360,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-16x9.webp"]},"summary":"Firm green papaya becomes tender, translucent strips as it gently cooks in panela syrup with cinnamon and cloves. This Colombian December sweet keeps the fruit in distinct pieces rather than turning it into jam.","ingredients":[{"name":"firm green papaya, peeled and deseeded; prepared weight","amount":"1000","unit":"g"},{"name":"grated panela","amount":"450","unit":"g"},{"name":"water for soaking","amount":"2000","unit":"ml"},{"name":"water for the first cooking","amount":"2000","unit":"ml"},{"name":"water for the syrup","amount":"750","unit":"ml"},{"name":"cinnamon stick, about 3 g","amount":"1","unit":"piece"},{"name":"whole cloves, about 0.8 g","amount":"4","unit":"piece"}],"steps":[{"title":"Cut the papaya","content":"Cut the 1000 g prepared papaya into even strips approximately 1 × 1 × 6 cm.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-01.webp","image_alt":"Cut the papaya"},{"title":"Soak the strips","content":"Soak the strips in the 2000 ml cold water for 1 hour in the refrigerator at 4 °C or below.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-02.webp","image_alt":"Soak the strips"},{"title":"Rinse the papaya","content":"Rinse the strips with clean water to remove traces of latex; they should be well drained.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-03.webp","image_alt":"Rinse the papaya"},{"title":"Soften the fruit","content":"Cook the strips in the other 2000 ml water at a gentle boil for 10–15 minutes until flexible and easily pierced with a skewer.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-04.webp","image_alt":"Soften the fruit"},{"title":"Make the syrup","content":"Dissolve the 450 g panela in the 750 ml water with the cinnamon stick and 4 cloves over low heat for about 10 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-05.webp","image_alt":"Make the syrup"},{"title":"Simmer the papaya","content":"Cook the drained, softened papaya in the syrup, uncovered over low heat, for 45–60 minutes. The strips should become translucent and tender, and the syrup should lightly coat a spoon.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-06.webp","image_alt":"Simmer the papaya"},{"title":"Remove the spices","content":"Remove the cinnamon stick and all 4 cloves when cooking is finished.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-07.webp","image_alt":"Remove the spices"},{"title":"Cool the dessert","content":"Cool the papaya in its syrup in a shallow container for no more than 1 hour. Total time outside the refrigerator must not exceed 2 hours.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-08.webp","image_alt":"Cool the dessert"},{"title":"Refrigerate","content":"Refrigerate the covered container for at least 4 hours at 4 °C or below.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-09.webp","image_alt":"Refrigerate"},{"title":"Serve","content":"Divide the papaya and all its syrup into 10 servings. Serve cold or lightly chilled.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp","image_alt":"Serve"}],"notes":"<p>Choose truly green papaya with firm, pale flesh, not ripe orange-fleshed papaya. This is a stovetop recipe: water boils near 100 °C at sea level and at a lower temperature at altitude, so judge doneness by texture. Keep covered in its syrup at 4 °C or below for up to 5 days from preparation. This is a refrigerated dessert, not a shelf-stable preserve. If the syrup thickens before the fruit softens, add hot water a little at a time.</p>","category":"Desserts","course":"Desserts","cuisine":"Colombian","difficulty":"Medium","servings":10,"prep_time_minutes":25,"cook_time_minutes":80,"total_time_minutes":465,"excerpt":"Firm green papaya becomes tender, translucent strips as it gently cooks in panela syrup with cinnamon and cloves. This Colombian December sweet keeps the fruit in distinct pieces rather than turning it into jam.","content_html":"","keywords":["Colombian Green Papaya Dessert"],"gallery":[],"public_path":"/en/colombian-green-papaya-dessert","nutrition":{"calories":214.0,"protein_g":0.5,"carbs_g":55.0,"fat_g":0.3,"serving_size":"1/10","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Ingredient nutrients summed for the stated quantities and divided by servings.","note":"Per 1 of 10 servings, including one tenth of all the syrup, without accompaniments. Generic raw papaya approximates green papaya and brown sugar approximates panela; removed spices are excluded. Leaving syrup reduces sugar intake."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp"},{"language":"de","slug":"kolumbianisches-gruene-papaya-dessert","title":"Süße grüne Papaya aus Kolumbien","seo":{"title":"Süße grüne Papaya aus Kolumbien","description":"Grüne Papayastreifen in Panela-Sirup mit Zimt und Nelken. Kolumbianisches Weihnachtsdessert mit Garzeiten, klaren Garproben und Tipps zur Kühllagerung.","faq":[{"q":"Wann ist die Papaya fertig?","a":"Die Streifen sind durchscheinend, lassen sich leicht einstechen und behalten ihre Form. Der Sirup überzieht einen Löffel dünn."},{"q":"Geht auch reife Papaya?","a":"Für diese Konsistenz nicht. Feste grüne Papaya verträgt langes Garen; reife kann zerfallen."}],"author":"Néstor Bastidas","image_alt":"Süße grüne Papaya aus Kolumbien","additional_time_minutes":360,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-16x9.webp"]},"summary":"Feste grüne Papaya wird in Panela-Sirup mit Zimt und Nelken zu zarten, durchscheinenden Streifen. Bei diesem kolumbianischen Dezemberdessert bleibt die Frucht in Stücken und wird nicht zu Marmelade.","ingredients":[{"name":"feste grüne Papaya, geschält und entkernt; vorbereitetes Gewicht","amount":"1000","unit":"g"},{"name":"geriebene Panela","amount":"450","unit":"g"},{"name":"Wasser zum Einweichen","amount":"2000","unit":"ml"},{"name":"Wasser zum ersten Garen","amount":"2000","unit":"ml"},{"name":"Wasser für den Sirup","amount":"750","unit":"ml"},{"name":"Zimtstange, etwa 3 g","amount":"1","unit":"Stück"},{"name":"ganze Gewürznelken, etwa 0,8 g","amount":"4","unit":"Stück"}],"steps":[{"title":"Papaya schneiden","content":"Die 1000 g vorbereitete Papaya in gleichmäßige Streifen von etwa 1 × 1 × 6 cm schneiden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-01.webp","image_alt":"Papaya schneiden"},{"title":"Streifen einweichen","content":"Die Streifen in den 2000 ml kaltem Wasser 1 Stunde bei höchstens 4 °C im Kühlschrank einweichen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-02.webp","image_alt":"Streifen einweichen"},{"title":"Papaya abspülen","content":"Die Streifen mit sauberem Wasser abspülen, um Milchsaftreste zu entfernen; sie sollen gut abgetropft sein.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-03.webp","image_alt":"Papaya abspülen"},{"title":"Frucht weich garen","content":"Die Streifen in den weiteren 2000 ml Wasser 10–15 Minuten sanft kochen, bis sie biegsam sind und sich leicht mit einem Holzstäbchen durchstechen lassen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-04.webp","image_alt":"Frucht weich garen"},{"title":"Sirup zubereiten","content":"Die 450 g Panela in den 750 ml Wasser mit der Zimtstange und 4 Nelken bei kleiner Hitze etwa 10 Minuten auflösen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-05.webp","image_alt":"Sirup zubereiten"},{"title":"Papaya im Sirup garen","content":"Die weich gegarte, abgetropfte Papaya offen bei kleiner Hitze 45–60 Minuten im Sirup garen. Die Streifen sollen durchscheinend und zart sein; der Sirup soll einen Löffel dünn überziehen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-06.webp","image_alt":"Papaya im Sirup garen"},{"title":"Gewürze entfernen","content":"Nach dem Garen die Zimtstange und alle 4 Nelken entfernen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-07.webp","image_alt":"Gewürze entfernen"},{"title":"Dessert abkühlen","content":"Die Papaya samt Sirup in einem flachen Gefäß höchstens 1 Stunde abkühlen lassen. Insgesamt darf sie nicht länger als 2 Stunden außerhalb des Kühlschranks stehen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-08.webp","image_alt":"Dessert abkühlen"},{"title":"Kalt stellen","content":"Das verschlossene Gefäß mindestens 4 Stunden bei höchstens 4 °C kühlen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-09.webp","image_alt":"Kalt stellen"},{"title":"Servieren","content":"Papaya und gesamten Sirup auf 10 Portionen verteilen. Kalt oder leicht gekühlt servieren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp","image_alt":"Servieren"}],"notes":"<p>Wirklich grüne Papaya mit festem, hellem Fruchtfleisch verwenden, keine reife orangefarbene. Das Dessert wird auf dem Herd gekocht: Wasser siedet auf Meereshöhe nahe 100 °C, in Höhenlagen niedriger; entscheidend ist die Konsistenz. Im Sirup verschlossen bei höchstens 4 °C bis zu 5 Tage ab Zubereitung aufbewahren. Es ist ein Kühlschrankdessert, keine bei Raumtemperatur lagerfähige Konserve. Wird der Sirup vorzeitig dick, nach und nach heißes Wasser zugeben.</p>","category":"Desserts","course":"Desserts","cuisine":"Kolumbianisch","difficulty":"Mittel","servings":10,"prep_time_minutes":25,"cook_time_minutes":80,"total_time_minutes":465,"excerpt":"Feste grüne Papaya wird in Panela-Sirup mit Zimt und Nelken zu zarten, durchscheinenden Streifen. Bei diesem kolumbianischen Dezemberdessert bleibt die Frucht in Stücken und wird nicht zu Marmelade.","content_html":"","keywords":["Süße grüne Papaya aus Kolumbien"],"gallery":[],"public_path":"/de/kolumbianisches-gruene-papaya-dessert","nutrition":{"calories":214.0,"protein_g":0.5,"carbs_g":55.0,"fat_g":0.3,"serving_size":"1/10","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Nährstoffe der angegebenen Zutatenmengen addiert und durch die Portionen geteilt.","note":"Für 1 von 10 Portionen einschließlich eines Zehntels des gesamten Sirups, ohne Beilagen. Allgemeine Werte für rohe Papaya und braunen Zucker nähern grüne Papaya und Panela an; entfernte Gewürze sind ausgeschlossen. Übriger Sirup senkt die Zuckeraufnahme."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp"},{"language":"fr","slug":"dessert-colombien-papaye-verte","title":"Papaye verte confite colombienne","seo":{"title":"Papaye verte confite colombienne","description":"Papaye verte en lanières au sirop de panela, cannelle et girofle. Dessert colombien de Noël avec temps précis, repères de cuisson et conservation au frais.","faq":[{"q":"Comment reconnaître la bonne cuisson ?","a":"Les lanières sont translucides, tendres sous la pointe et gardent leur forme. Le sirop nappe légèrement une cuillère."},{"q":"Peut-on utiliser une papaye mûre ?","a":"Pas pour cette texture. La papaye verte ferme supporte une longue cuisson ; la papaye mûre risque de se défaire."}],"author":"Néstor Bastidas","image_alt":"Papaye verte confite colombienne","additional_time_minutes":360,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-16x9.webp"]},"summary":"La papaye verte ferme devient tendre et translucide dans un sirop de panela parfumé à la cannelle et au girofle. Cette douceur colombienne de décembre garde de belles lanières de fruit, sans les réduire en confiture.","ingredients":[{"name":"papaye verte ferme, pelée et épépinée ; poids net","amount":"1000","unit":"g"},{"name":"panela râpée","amount":"450","unit":"g"},{"name":"eau pour le trempage","amount":"2000","unit":"ml"},{"name":"eau pour la première cuisson","amount":"2000","unit":"ml"},{"name":"eau pour le sirop","amount":"750","unit":"ml"},{"name":"bâton de cannelle, environ 3 g","amount":"1","unit":"pièce"},{"name":"clous de girofle entiers, environ 0,8 g","amount":"4","unit":"pièce"}],"steps":[{"title":"Taillez la papaye","content":"Taillez les 1000 g de papaye préparée en lanières régulières d’environ 1 × 1 × 6 cm.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-01.webp","image_alt":"Taillez la papaye"},{"title":"Faites tremper","content":"Faites tremper les lanières dans les 2000 ml d’eau froide pendant 1 heure au réfrigérateur à 4 °C ou moins.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-02.webp","image_alt":"Faites tremper"},{"title":"Rincez la papaye","content":"Rincez les lanières à l’eau propre pour retirer les traces de latex ; elles doivent être bien égouttées.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-03.webp","image_alt":"Rincez la papaye"},{"title":"Attendrissez le fruit","content":"Cuisez les lanières dans les 2000 ml d’eau supplémentaires à petits bouillons pendant 10–15 minutes : elles doivent être souples et faciles à piquer.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-04.webp","image_alt":"Attendrissez le fruit"},{"title":"Préparez le sirop","content":"Dissolvez les 450 g de panela dans les 750 ml d’eau avec la cannelle et les 4 clous de girofle, à feu doux pendant environ 10 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-05.webp","image_alt":"Préparez le sirop"},{"title":"Confisez la papaye","content":"Cuisez la papaye précuite et égouttée dans le sirop, à découvert et à feu doux, pendant 45–60 minutes. Les lanières doivent être translucides et tendres ; le sirop doit napper légèrement une cuillère.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-06.webp","image_alt":"Confisez la papaye"},{"title":"Retirez les épices","content":"Retirez le bâton de cannelle et les 4 clous de girofle à la fin de la cuisson.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-07.webp","image_alt":"Retirez les épices"},{"title":"Laissez refroidir","content":"Refroidissez la papaye dans son sirop, dans un récipient peu profond, pendant 1 heure maximum. Le temps total hors du réfrigérateur ne doit pas dépasser 2 heures.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-08.webp","image_alt":"Laissez refroidir"},{"title":"Réfrigérez","content":"Réfrigérez le récipient fermé au moins 4 heures à 4 °C ou moins.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-09.webp","image_alt":"Réfrigérez"},{"title":"Servez","content":"Répartissez la papaye et tout son sirop en 10 portions. Servez froid ou légèrement frais.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp","image_alt":"Servez"}],"notes":"<p>Choisissez une papaye vraiment verte, à chair ferme et pâle, et non une papaye mûre orange. La recette se fait sur le feu : l’eau bout près de 100 °C au niveau de la mer et plus bas en altitude ; fiez-vous à la texture. Gardez fermé dans le sirop à 4 °C ou moins pendant 5 jours maximum après préparation. Ce dessert se conserve au réfrigérateur, pas dans un placard. Si le sirop épaissit avant que le fruit soit tendre, ajoutez un peu d’eau chaude à la fois.</p>","category":"Desserts","course":"Desserts","cuisine":"Colombienne","difficulty":"Intermédiaire","servings":10,"prep_time_minutes":25,"cook_time_minutes":80,"total_time_minutes":465,"excerpt":"La papaye verte ferme devient tendre et translucide dans un sirop de panela parfumé à la cannelle et au girofle. Cette douceur colombienne de décembre garde de belles lanières de fruit, sans les réduire en confiture.","content_html":"","keywords":["Papaye verte confite colombienne"],"gallery":[],"public_path":"/fr/dessert-colombien-papaye-verte","nutrition":{"calories":214.0,"protein_g":0.5,"carbs_g":55.0,"fat_g":0.3,"serving_size":"1/10","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Somme des nutriments des quantités indiquées, divisée par le nombre de portions.","note":"Pour 1 portion sur 10, avec un dixième de tout le sirop, sans accompagnement. Papaye crue générique et sucre brun servent d’équivalents à la papaye verte et à la panela ; les épices retirées sont exclues. Laisser du sirop réduit le sucre consommé."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp"},{"language":"it","slug":"dolce-colombiano-papaya-verde","title":"Dolce colombiano di papaya verde","seo":{"title":"Dolce colombiano di papaya verde","description":"Papaya verde a strisce nello sciroppo di panela, cannella e chiodi di garofano. Dolce natalizio colombiano con tempi, punto di cottura e conservazione.","faq":[{"q":"Come capisco che è pronta?","a":"Le strisce sono traslucide, tenere quando le pungi e mantengono la forma. Lo sciroppo vela leggermente un cucchiaio."},{"q":"Posso usare papaya matura?","a":"Non per questa consistenza. Quella verde e soda regge una lunga cottura; la papaya matura può disfarsi."}],"author":"Néstor Bastidas","image_alt":"Dolce colombiano di papaya verde","additional_time_minutes":360,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-16x9.webp"]},"summary":"La papaya verde e soda diventa tenera e traslucida nello sciroppo di panela con cannella e chiodi di garofano. Questo dolce colombiano di dicembre conserva la frutta a strisce, senza trasformarla in confettura.","ingredients":[{"name":"papaya verde soda, pelata e senza semi; peso pulito","amount":"1000","unit":"g"},{"name":"panela grattugiata","amount":"450","unit":"g"},{"name":"acqua per l’ammollo","amount":"2000","unit":"ml"},{"name":"acqua per la prima cottura","amount":"2000","unit":"ml"},{"name":"acqua per lo sciroppo","amount":"750","unit":"ml"},{"name":"stecca di cannella, circa 3 g","amount":"1","unit":"pezzo"},{"name":"chiodi di garofano interi, circa 0,8 g","amount":"4","unit":"pezzo"}],"steps":[{"title":"Taglia la papaya","content":"Taglia i 1000 g di papaya pulita a strisce regolari di circa 1 × 1 × 6 cm.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-01.webp","image_alt":"Taglia la papaya"},{"title":"Metti in ammollo","content":"Lascia le strisce nei 2000 ml d’acqua fredda per 1 ora in frigorifero a 4 °C o meno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-02.webp","image_alt":"Metti in ammollo"},{"title":"Risciacqua la papaya","content":"Risciacqua le strisce con acqua pulita per eliminare tracce di lattice; devono essere ben scolate.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-03.webp","image_alt":"Risciacqua la papaya"},{"title":"Ammorbidisci la frutta","content":"Cuoci le strisce negli altri 2000 ml d’acqua a leggero bollore per 10–15 minuti, finché diventano flessibili e uno stecchino entra facilmente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-04.webp","image_alt":"Ammorbidisci la frutta"},{"title":"Prepara lo sciroppo","content":"Sciogli i 450 g di panela nei 750 ml d’acqua con la cannella e i 4 chiodi di garofano, a fuoco basso per circa 10 minuti.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-05.webp","image_alt":"Prepara lo sciroppo"},{"title":"Cuoci nello sciroppo","content":"Cuoci la papaya precotta e scolata nello sciroppo, scoperta e a fuoco basso, per 45–60 minuti. Le strisce devono essere traslucide e tenere e lo sciroppo velare leggermente un cucchiaio.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-06.webp","image_alt":"Cuoci nello sciroppo"},{"title":"Togli le spezie","content":"Togli la stecca di cannella e tutti e 4 i chiodi di garofano al termine della cottura.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-07.webp","image_alt":"Togli le spezie"},{"title":"Fai raffreddare","content":"Fai raffreddare la papaya nel suo sciroppo in un recipiente basso per non più di 1 ora. Il tempo totale fuori dal frigorifero non deve superare 2 ore.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-08.webp","image_alt":"Fai raffreddare"},{"title":"Metti in frigorifero","content":"Conserva il recipiente chiuso in frigorifero per almeno 4 ore a 4 °C o meno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-09.webp","image_alt":"Metti in frigorifero"},{"title":"Servi","content":"Dividi la papaya e tutto lo sciroppo in 10 porzioni. Servi fredda o leggermente fresca.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp","image_alt":"Servi"}],"notes":"<p>Scegli papaya davvero verde, con polpa soda e chiara, non papaya matura arancione. Si cuoce sul fornello: l’acqua bolle vicino a 100 °C al livello del mare e a temperature inferiori in quota; valuta il punto dalla consistenza. Conserva chiusa nel suo sciroppo a 4 °C o meno per un massimo di 5 giorni dalla preparazione. È un dolce da frigorifero, non una conserva da dispensa. Se lo sciroppo si addensa prima che la frutta sia tenera, aggiungi poca acqua calda alla volta.</p>","category":"Dolci","course":"Dolci","cuisine":"Colombiana","difficulty":"Media","servings":10,"prep_time_minutes":25,"cook_time_minutes":80,"total_time_minutes":465,"excerpt":"La papaya verde e soda diventa tenera e traslucida nello sciroppo di panela con cannella e chiodi di garofano. Questo dolce colombiano di dicembre conserva la frutta a strisce, senza trasformarla in confettura.","content_html":"","keywords":["Dolce colombiano di papaya verde"],"gallery":[],"public_path":"/it/dolce-colombiano-papaya-verde","nutrition":{"calories":214.0,"protein_g":0.5,"carbs_g":55.0,"fat_g":0.3,"serving_size":"1/10","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Somma dei nutrienti delle quantità indicate divisa per il numero di porzioni.","note":"Per 1 delle 10 porzioni, con un decimo di tutto lo sciroppo, senza accompagnamenti. Papaya cruda generica e zucchero di canna approssimano papaya verde e panela; le spezie tolte sono escluse. Lasciare sciroppo riduce lo zucchero consumato."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp"},{"language":"ja","slug":"colombia-green-papaya-dulce","title":"青パパイヤのコロンビア風甘煮","seo":{"title":"青パパイヤのコロンビア風甘煮","description":"青パパイヤを細長く切り、パネラ、シナモン、クローブのシロップでじっくり煮るコロンビアの冬のデザート。透明感が出てやわらかくなる火の通し方を紹介します。下ゆでと煮込みの時間、シロップの仕上がりの目安、冷やし方、冷蔵での保存期間までわかるレシピです。","faq":[{"q":"煮上がりの目安は？","a":"棒状のパパイヤに透明感が出て、串がすっと通り、形は残っている状態です。シロップはスプーンを薄く覆う濃さにします。"},{"q":"熟したパパイヤでも作れますか？","a":"同じ食感にはなりません。かたい青パパイヤは長く煮ても形が残りやすく、熟したものは煮崩れしやすいためです。"}],"author":"Néstor Bastidas","image_alt":"青パパイヤのコロンビア風甘煮","additional_time_minutes":360,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-16x9.webp"]},"summary":"かたい青パパイヤをパネラのシロップで煮ると、形を残したままやわらかく、つやと透明感のある甘煮になります。シナモンとクローブが香る、コロンビアの12月の家庭のデザートです。","ingredients":[{"name":"かたい青パパイヤ（皮と種を除いた正味重量）","amount":"1000","unit":"g"},{"name":"細かくしたパネラ","amount":"450","unit":"g"},{"name":"浸水用の水","amount":"2000","unit":"ml"},{"name":"下ゆで用の水","amount":"2000","unit":"ml"},{"name":"シロップ用の水","amount":"750","unit":"ml"},{"name":"シナモンスティック（約3 g）","amount":"1","unit":"本"},{"name":"クローブ（ホール、約0.8 g）","amount":"4","unit":"粒"}],"steps":[{"title":"パパイヤを切る","content":"正味1000 gの青パパイヤを、約1 × 1 × 6 cmの均一な棒状に切ります。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-01.webp","image_alt":"パパイヤを切る"},{"title":"水に浸す","content":"冷たい水2000 mlに浸し、4 °C以下の冷蔵庫で1時間置きます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-02.webp","image_alt":"水に浸す"},{"title":"パパイヤをすすぐ","content":"きれいな水ですすぎ、乳液の残りを落とします。水けがよく切れた状態にします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-03.webp","image_alt":"パパイヤをすすぐ"},{"title":"下ゆでする","content":"別の水2000 mlで10～15分静かにゆでます。曲がるくらいやわらかくなり、竹串がすっと通れば十分です。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-04.webp","image_alt":"下ゆでする"},{"title":"シロップを作る","content":"パネラ450 g、水750 ml、シナモン1本、クローブ4粒を弱火で約10分煮て溶かします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-05.webp","image_alt":"シロップを作る"},{"title":"シロップで煮る","content":"下ゆでして水けを切ったパパイヤをシロップに入れ、ふたをせず弱火で45～60分煮ます。透明感が出てやわらかくなり、シロップがスプーンを薄く覆えば仕上がりです。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-06.webp","image_alt":"シロップで煮る"},{"title":"香辛料を取り出す","content":"煮上がったらシナモン1本とクローブ4粒を取り出します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-07.webp","image_alt":"香辛料を取り出す"},{"title":"粗熱を取る","content":"シロップごと浅い容器に入れ、1時間以内を目安に冷まします。冷蔵庫の外に置く合計時間は2時間を超えないようにします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-08.webp","image_alt":"粗熱を取る"},{"title":"冷蔵する","content":"ふたをした容器を4 °C以下の冷蔵庫に入れ、4時間以上冷やします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-09.webp","image_alt":"冷蔵する"},{"title":"盛りつける","content":"パパイヤとシロップ全量を10人分に分けます。冷たい状態、または少し冷えた状態で出します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp","image_alt":"盛りつける"}],"notes":"<p>果肉がかたく色の淡い、本当に青いパパイヤを使います。オレンジ色に熟したものは向きません。鍋で作るレシピです。水の沸点は海面付近で約100 °C、高地では低くなるため、やわらかさを目安にしてください。シロップに浸したままふたをし、4 °C以下で作ってから5日以内に食べ切ります。常温保存用の瓶詰めではありません。果肉がやわらかくなる前にシロップが濃くなったら、湯を少量ずつ加えます。</p>","category":"デザート","course":"デザート","cuisine":"コロンビア料理","difficulty":"中級","servings":10,"prep_time_minutes":25,"cook_time_minutes":80,"total_time_minutes":465,"excerpt":"かたい青パパイヤをパネラのシロップで煮ると、形を残したままやわらかく、つやと透明感のある甘煮になります。シナモンとクローブが香る、コロンビアの12月の家庭のデザートです。","content_html":"","keywords":["青パパイヤのコロンビア風甘煮"],"gallery":[],"public_path":"/ja/colombia-green-papaya-dulce","nutrition":{"calories":214.0,"protein_g":0.5,"carbs_g":55.0,"fat_g":0.3,"serving_size":"1/10","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"材料の分量から栄養を合計し、人数分で割った推定値です。","note":"10等分の1人分。シロップ全量の10分の1を含み、付け合わせは除きます。青パパイヤは一般的な生パパイヤ、パネラはブラウンシュガーで近似。取り除く香辛料は計算外です。シロップを残すと糖分の摂取量は減ります。"},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp"},{"language":"pt","slug":"doce-de-mamao-verde","title":"Doce de mamão verde colombiano","seo":{"title":"Doce de mamão verde colombiano","description":"Doce de mamão verde em tiras com calda de panela, canela e cravo. Sobremesa colombiana de dezembro, com tempos, ponto da fruta e conservação na geladeira.","faq":[{"q":"Como sei que está pronto?","a":"As tiras devem estar translúcidas, macias ao espetar e inteiras. A calda deve cobrir levemente uma colher."},{"q":"Posso usar mamão maduro?","a":"Não para essa textura. O mamão verde firme aguenta o cozimento longo; o maduro pode se desfazer."}],"author":"Néstor Bastidas","image_alt":"Doce de mamão verde colombiano","additional_time_minutes":360,"image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada-16x9.webp"]},"summary":"O mamão verde e firme fica macio e translúcido ao cozinhar na calda de panela com canela e cravo. Este doce caseiro colombiano de dezembro preserva as tiras da fruta, sem virar geleia.","ingredients":[{"name":"mamão verde firme, descascado e sem sementes; peso limpo","amount":"1000","unit":"g"},{"name":"panela ralada","amount":"450","unit":"g"},{"name":"água para deixar de molho","amount":"2000","unit":"ml"},{"name":"água para a primeira cocção","amount":"2000","unit":"ml"},{"name":"água para a calda","amount":"750","unit":"ml"},{"name":"canela em pau, cerca de 3 g","amount":"1","unit":"unidade"},{"name":"cravos-da-índia inteiros, cerca de 0,8 g","amount":"4","unit":"unidade"}],"steps":[{"title":"Corte o mamão","content":"Corte os 1000 g de mamão limpo em tiras regulares de aproximadamente 1 × 1 × 6 cm.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-01.webp","image_alt":"Corte o mamão"},{"title":"Deixe de molho","content":"Deixe as tiras nos 2000 ml de água fria por 1 hora na geladeira a 4 °C ou menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-02.webp","image_alt":"Deixe de molho"},{"title":"Enxágue o mamão","content":"Enxágue as tiras com água limpa para retirar restos de látex; elas devem ficar bem escorridas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-03.webp","image_alt":"Enxágue o mamão"},{"title":"Amacie a fruta","content":"Cozinhe as tiras nos outros 2000 ml de água em fervura suave por 10–15 minutos, até ficarem flexíveis e um palito entrar facilmente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-04.webp","image_alt":"Amacie a fruta"},{"title":"Prepare a calda","content":"Dissolva os 450 g de panela nos 750 ml de água com a canela e os 4 cravos, em fogo baixo por cerca de 10 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-05.webp","image_alt":"Prepare a calda"},{"title":"Cozinhe na calda","content":"Cozinhe o mamão pré-cozido e escorrido na calda, destampado e em fogo baixo, por 45–60 minutos. As tiras devem ficar translúcidas e macias, e a calda cobrir levemente uma colher.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-06.webp","image_alt":"Cozinhe na calda"},{"title":"Retire as especiarias","content":"Retire a canela em pau e os 4 cravos ao terminar a cocção.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-07.webp","image_alt":"Retire as especiarias"},{"title":"Esfrie o doce","content":"Esfrie o mamão com a calda num recipiente raso por no máximo 1 hora. O tempo total fora da geladeira não deve passar de 2 horas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-08.webp","image_alt":"Esfrie o doce"},{"title":"Leve à geladeira","content":"Refrigere o recipiente tampado por pelo menos 4 horas a 4 °C ou menos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/paso-09.webp","image_alt":"Leve à geladeira"},{"title":"Sirva","content":"Divida o mamão e toda a calda em 10 porções. Sirva gelado ou levemente fresco.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp","image_alt":"Sirva"}],"notes":"<p>Use mamão realmente verde, com polpa firme e clara, não mamão maduro de polpa laranja. O preparo é no fogão: a água ferve perto de 100 °C ao nível do mar e a temperaturas menores em altitude; avalie o ponto pela textura. Guarde tampado na própria calda a 4 °C ou menos por até 5 dias após o preparo. É um doce refrigerado, não uma conserva para guardar no armário. Se a calda engrossar antes de a fruta amaciar, adicione água quente aos poucos.</p>","category":"Sobremesas","course":"Sobremesas","cuisine":"Colombiana","difficulty":"Média","servings":10,"prep_time_minutes":25,"cook_time_minutes":80,"total_time_minutes":465,"excerpt":"O mamão verde e firme fica macio e translúcido ao cozinhar na calda de panela com canela e cravo. Este doce caseiro colombiano de dezembro preserva as tiras da fruta, sem virar geleia.","content_html":"","keywords":["Doce de mamão verde colombiano"],"gallery":[],"public_path":"/pt/doce-de-mamao-verde","nutrition":{"calories":214.0,"protein_g":0.5,"carbs_g":55.0,"fat_g":0.3,"serving_size":"1/10","estimated":true,"source":"USDA FoodData Central / Standard Reference","method":"Soma dos nutrientes das quantidades indicadas dividida pelo número de porções.","note":"Por 1 das 10 porções, com um décimo de toda a calda, sem acompanhamentos. Mamão cru genérico e açúcar mascavo aproximam mamão verde e panela; as especiarias retiradas não entram. Deixar calda reduz o açúcar consumido."},"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-papaya-verde/portada.webp"}]]$content$::jsonb;
 aliases jsonb := $aliases$[{"slug":"leche","alias":"leche entera pasteurizada"},{"slug":"yema-de-huevo","alias":"yemas de huevo, unas 6 grandes; pesar 108 g"},{"slug":"azucar","alias":"azúcar blanca"},{"slug":"canela-molida","alias":"canela molida"},{"slug":"brandy","alias":"brandy al 40 % vol o aguardiente colombiano"},{"slug":"uvas-pasas","alias":"uvas pasas sin semillas"},{"slug":"ciruelas-pasas","alias":"ciruelas pasas sin hueso, picadas"},{"slug":"cascara-de-naranja-confitada","alias":"cáscara de naranja confitada, picada"},{"slug":"vino-tinto","alias":"vino tinto dulce al 12 % vol"},{"slug":"panela","alias":"panela rallada"},{"slug":"agua","alias":"agua para caramelizar la panela"},{"slug":"agua","alias":"agua hirviendo para diluir el caramelo"},{"slug":"mantequilla","alias":"mantequilla sin sal, blanda"},{"slug":"azucar","alias":"azúcar blanca"},{"slug":"huevo","alias":"huevos, unos 4 grandes sin cáscara; pesar 200 g"},{"slug":"harina-de-trigo","alias":"harina de trigo común"},{"slug":"polvo-de-hornear","alias":"polvo de hornear"},{"slug":"canela-molida","alias":"canela molida"},{"slug":"clavo-de-olor","alias":"clavo de olor molido"},{"slug":"sal","alias":"sal"},{"slug":"papaya-verde","alias":"papaya verde firme, pelada y sin semillas; peso limpio"},{"slug":"panela","alias":"panela rallada"},{"slug":"agua","alias":"agua para remojar"},{"slug":"agua","alias":"agua para la primera cocción"},{"slug":"agua","alias":"agua para el almíbar"},{"slug":"canela-en-rama","alias":"canela en rama, unos 3 g"},{"slug":"clavo-de-olor","alias":"clavos de olor enteros, unos 0,8 g"}]$aliases$::jsonb;
 repairs jsonb := $repairs$[{"group":"e5d6b548-da6a-4015-8367-e2dcf41017d7","index":2,"url":"tamal-tolimense/paso-03-completo.webp"},{"group":"14e6c47c-544b-4632-bd30-369f54042a61","index":2,"url":"pernil-de-cerdo-al-horno/paso-03-completo.webp"},{"group":"14e6c47c-544b-4632-bd30-369f54042a61","index":5,"url":"pernil-de-cerdo-al-horno/paso-06-completo.webp"},{"group":"14e6c47c-544b-4632-bd30-369f54042a61","index":6,"url":"pernil-de-cerdo-al-horno/paso-07-completo.webp"}]$repairs$::jsonb;
 payload jsonb; v_source uuid; v_group uuid; v_alias jsonb; v_id uuid; v_n integer; promotion record; repair jsonb; image text; idx integer;
BEGIN
 FOR payload IN SELECT x FROM jsonb_array_elements(bundles) x LOOP
 IF EXISTS (SELECT 1 FROM public.recipes WHERE slug IN (SELECT x->>'slug' FROM jsonb_array_elements(payload) x))
 OR EXISTS (SELECT 1 FROM public.content_pages WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x))
 OR EXISTS (SELECT 1 FROM public.content_redirects WHERE source_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x)) THEN RAISE EXCEPTION 'A recipe or route already exists'; END IF;
 END LOOP;
 FOR promotion IN SELECT * FROM (VALUES
 ('4d37753a-6dca-4ee6-95dd-be22b530534f'::uuid,'brandy','Brandy'),
 ('017326c4-246a-4bbe-b079-3f28d2854d3d'::uuid,'canela-molida','Canela molida'),
 ('b16ab14f-772f-41fb-88a6-6598c07d87d0'::uuid,'yema-de-huevo','Yema de huevo'),
 ('6fcf44a5-147f-47c5-bd1b-dcc6183381b2'::uuid,'papaya-verde','Papaya verde'),
 ('122a72e4-2270-4db4-b09b-a5bcc2727c45'::uuid,'uvas-pasas','Uvas pasas'),
 ('bf5371d9-9cb3-4eaa-8a8b-ff499377ad58'::uuid,'vino-tinto','Vino tinto')) p(id,slug,name) LOOP
 IF EXISTS(SELECT 1 FROM public.ingredients i WHERE i.slug=promotion.slug AND i.id<>promotion.id) THEN RAISE EXCEPTION 'Canonical identity collision'; END IF;
 UPDATE public.ingredients i SET slug=promotion.slug,name=promotion.name,normalized_name=lower(promotion.name),status='canonical',searchable=true,indexable=false WHERE i.id=promotion.id AND i.status IN ('pending','review');
 END LOOP;
 INSERT INTO public.ingredients(name,normalized_name,slug,description,status,searchable,indexable)
 SELECT name,lower(name),slug,description,'canonical',true,false FROM (VALUES
 ('Ciruelas pasas','ciruelas-pasas','Ciruelas deshidratadas sin hueso, para cocinar y repostería.'),
 ('Cáscara de naranja confitada','cascara-de-naranja-confitada','Piel de naranja cocida y conservada en azúcar, para repostería.')) n(name,slug,description)
 WHERE NOT EXISTS(SELECT 1 FROM public.ingredients i WHERE i.slug=n.slug);
 FOR v_alias IN SELECT x FROM jsonb_array_elements(aliases) x LOOP
 SELECT id INTO STRICT v_id FROM public.ingredients WHERE slug=v_alias->>'slug' AND status='canonical' AND searchable;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases a JOIN public.ingredients i ON i.id=a.ingredient_id WHERE a.normalized_alias=lower(v_alias->>'alias') AND a.ingredient_id<>v_id AND i.status='canonical') THEN RAISE EXCEPTION 'Ingredient alias collision'; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) VALUES(v_id,v_alias->>'alias',lower(v_alias->>'alias')) ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
 END LOOP;
 FOR payload IN SELECT x FROM jsonb_array_elements(bundles) x LOOP
 INSERT INTO public.recipes(language, slug, title, excerpt, summary, ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url, content_html, notes, difficulty, course, cuisine, keywords, nutrition, seo, public_path, gallery,published,editorial_status)
 SELECT s.language, s.slug, s.title, s.excerpt, s.summary, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.total_time_minutes, s.servings, s.image_url, s.content_html, s.notes, s.difficulty, s.course, s.cuisine, s.keywords, s.nutrition, s.seo, s.public_path, s.gallery,false,'draft' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language='es'
 RETURNING id,recipe_group_id INTO v_source,v_group;
 INSERT INTO public.recipes(recipe_group_id,language, slug, title, excerpt, summary, ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url, content_html, notes, difficulty, course, cuisine, keywords, nutrition, seo, public_path, gallery,published,editorial_status)
 SELECT v_group,s.language, s.slug, s.title, s.excerpt, s.summary, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.total_time_minutes, s.servings, s.image_url, s.content_html, s.notes, s.difficulty, s.course, s.cuisine, s.keywords, s.nutrition, s.seo, s.public_path, s.gallery,false,'draft' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language<>'es';
 IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=v_source)<>jsonb_array_length(payload->0->'ingredients') OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=v_source) THEN RAISE EXCEPTION 'Ingredient mapping incomplete'; END IF;
 UPDATE public.recipes SET published=true,editorial_status='published',ready_at=coalesce(ready_at,now()) WHERE recipe_group_id=v_group;
 SELECT count(DISTINCT language) INTO v_n FROM public.recipes WHERE recipe_group_id=v_group AND published AND nutrition IS NOT NULL AND jsonb_array_length(steps)=jsonb_array_length(payload->0->'steps');
 IF v_n<>7 THEN RAISE EXCEPTION 'Incomplete seven-language publication'; END IF;
 END LOOP;
 FOR repair IN SELECT x FROM jsonb_array_elements(repairs) x LOOP
 idx:=(repair->>'index')::integer;image:='https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/'||(repair->>'url');
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=(repair->>'group')::uuid AND published AND jsonb_array_length(steps)=8)<>7 THEN RAISE EXCEPTION 'Unexpected source recipe versions'; END IF;
 IF EXISTS(SELECT 1 FROM public.recipes WHERE recipe_group_id=(repair->>'group')::uuid AND coalesce(steps->idx->>'image_url','') NOT IN ('',image)) THEN RAISE EXCEPTION 'Target image already changed'; END IF;
 UPDATE public.recipes SET steps=jsonb_set(jsonb_set(steps,ARRAY[idx::text,'image_url'],to_jsonb(image),true),ARRAY[idx::text,'image_alt'],to_jsonb(steps->idx->>'title'),true) WHERE recipe_group_id=(repair->>'group')::uuid;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.recipes r CROSS JOIN LATERAL jsonb_array_elements(r.steps) s WHERE r.recipe_group_id IN ('e5d6b548-da6a-4015-8367-e2dcf41017d7'::uuid,'14e6c47c-544b-4632-bd30-369f54042a61'::uuid) AND coalesce(s->>'image_url','')='') THEN RAISE EXCEPTION 'A recipe step still lacks an image'; END IF;
END $publish$;
COMMIT;
